INSERT INTO exercises VALUES ('barbell-bench-press', 'Press de Banca con Barra', 'Barbell Bench Press', 'Hipertrofia', 'Chest', 'Pecho / Pectoral', '["Shoulders","Triceps"]', 'Barbell', 'Barra Olímpica', 'Intermedio', 'Compuesto', 'Empuje Horizontal', 'Empuje', '', '["Acuéstate libremente en el banco plano, con la cabeza, espalda alta y glúteos apoyados.","Sujeta la barra con las manos un poco más anchas que los hombros.","Desengancha la barra de forma controlada y colócala sobre el centro del pecho.","Baja la barra lentamente doblando los codos a unos 45 grados de tu torso hasta rozar la línea media del pecho.","Empuja la barra con fuerza y estabilidad de regreso a la posición de brazos extendidos, sin bloquear los codos por completo."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/1.jpg"]', '[{"id":"dumbbell-bench-press","name":"Press de Banca con Mancuernas","nameEn":"Dumbbell Bench Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/1.jpg"]},{"id":"incline-dumbbell-bench-press","name":"Press de Banca Inclinado con Mancuernas","nameEn":"Incline Dumbbell Bench Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Press/1.jpg"]},{"id":"decline-dumbbell-bench-press","name":"Press de Banca Declinado con Mancuernas","nameEn":"Decline Dumbbell Bench Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Dumbbell_Bench_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Dumbbell_Bench_Press/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('dumbbell-bench-press', 'Press de Banca con Mancuernas', 'Dumbbell Bench Press', 'Hipertrofia', 'Chest', 'Pecho / Pectoral', '["Shoulders","Triceps"]', 'Dumbbell', 'Mancuernas', 'Principiante', 'Compuesto', 'Empuje Horizontal', 'Empuje', '', '["Siéntate en un banco plano con una mancuerna en cada rodilla.","Acuéstate hacia atrás mientras llevas las mancuernas al pecho con la ayuda de tus piernas.","Sostén las mancuernas sobre tu pecho alineadas con tus codos bajando a unos 90 grados.","Empuja las mancuernas hacia arriba en un movimiento semicircular controlado hacia el centro.","Baja de regreso estirando el pecho de forma constante."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/1.jpg"]', '[{"id":"barbell-bench-press","name":"Press de Banca con Barra","nameEn":"Barbell Bench Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/1.jpg"]},{"id":"incline-barbell-bench-press","name":"Press de Banca Inclinado con Barra","nameEn":"Incline Barbell Bench Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/1.jpg"]},{"id":"decline-barbell-bench-press","name":"Press de Banca Declinado con Barra","nameEn":"Decline Barbell Bench Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Barbell_Bench_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Barbell_Bench_Press/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('incline-barbell-bench-press', 'Press de Banca Inclinado con Barra', 'Incline Barbell Bench Press', 'Hipertrofia', 'Chest', 'Pecho / Pectoral', '["Shoulders","Triceps"]', 'Barbell', 'Barra Olímpica', 'Intermedio', 'Compuesto', 'Empuje Horizontal', 'Empuje', '', '["Alinea el banco a unos 30 o 45 grados de inclinación.","Acuéstate bocarriba y toma la barra un poco más ancha que tus hombros.","Retira la barra del soporte y bájala lentamente hacia la parte alta del pecho.","Empuja con los tríceps y el pecho alto para subir el peso verticalmente.","Inhala al bajar, exhala con fuerza al empujar el peso."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/1.jpg"]', '[{"id":"dumbbell-bench-press","name":"Press de Banca con Mancuernas","nameEn":"Dumbbell Bench Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/1.jpg"]},{"id":"incline-dumbbell-bench-press","name":"Press de Banca Inclinado con Mancuernas","nameEn":"Incline Dumbbell Bench Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Press/1.jpg"]},{"id":"decline-dumbbell-bench-press","name":"Press de Banca Declinado con Mancuernas","nameEn":"Decline Dumbbell Bench Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Dumbbell_Bench_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Dumbbell_Bench_Press/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('incline-dumbbell-bench-press', 'Press de Banca Inclinado con Mancuernas', 'Incline Dumbbell Bench Press', 'Hipertrofia', 'Chest', 'Pecho / Pectoral', '["Shoulders","Triceps"]', 'Dumbbell', 'Mancuernas', 'Principiante', 'Compuesto', 'Empuje Horizontal', 'Empuje', '', '["Asegura una inclinación del banco entre 30 y 45 grados.","Empuja las mancuernas hacia arriba empezando desde los lados de tus hombros superiores.","Controla el descenso de manera que tus codos formen un ángulo cómodo e higiénico.","Asegúrate de no chocar las mancuernas al tope de la fase de ascenso para mantener tensión."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Press/1.jpg"]', '[{"id":"barbell-bench-press","name":"Press de Banca con Barra","nameEn":"Barbell Bench Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/1.jpg"]},{"id":"incline-barbell-bench-press","name":"Press de Banca Inclinado con Barra","nameEn":"Incline Barbell Bench Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/1.jpg"]},{"id":"decline-barbell-bench-press","name":"Press de Banca Declinado con Barra","nameEn":"Decline Barbell Bench Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Barbell_Bench_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Barbell_Bench_Press/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('decline-barbell-bench-press', 'Press de Banca Declinado con Barra', 'Decline Barbell Bench Press', 'Hipertrofia', 'Chest', 'Pecho / Pectoral', '["Shoulders","Triceps"]', 'Barbell', 'Barra Olímpica', 'Intermedio', 'Compuesto', 'Empuje Horizontal', 'Empuje', '', '["Asegura tus piernas en el soporte del banco declinado y acuéstate.","Toma la barra con un agarre prono un poco más ancho que los hombros.","Saca la barra del rack y bájala controladamente hacia la parte inferior del pecho.","Empuja verticalmente hacia arriba contrayendo el pectoral inferior."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Barbell_Bench_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Barbell_Bench_Press/1.jpg"]', '[{"id":"dumbbell-bench-press","name":"Press de Banca con Mancuernas","nameEn":"Dumbbell Bench Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/1.jpg"]},{"id":"incline-dumbbell-bench-press","name":"Press de Banca Inclinado con Mancuernas","nameEn":"Incline Dumbbell Bench Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Press/1.jpg"]},{"id":"decline-dumbbell-bench-press","name":"Press de Banca Declinado con Mancuernas","nameEn":"Decline Dumbbell Bench Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Dumbbell_Bench_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Dumbbell_Bench_Press/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('decline-dumbbell-bench-press', 'Press de Banca Declinado con Mancuernas', 'Decline Dumbbell Bench Press', 'Hipertrofia', 'Chest', 'Pecho / Pectoral', '["Shoulders","Triceps"]', 'Dumbbell', 'Mancuernas', 'Principiante', 'Compuesto', 'Empuje Horizontal', 'Empuje', '', '["Siéntate en el banco declinado sosteniendo las mancuernas sobre los muslos.","Acuéstate hacia atrás controlando el peso a los lados del pecho inferior.","Empuja las mancuernas hacia arriba bloqueando suavemente arriba.","Baja sintiendo el estiramiento en la porción inferior del pectoral."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Dumbbell_Bench_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Dumbbell_Bench_Press/1.jpg"]', '[{"id":"barbell-bench-press","name":"Press de Banca con Barra","nameEn":"Barbell Bench Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/1.jpg"]},{"id":"incline-barbell-bench-press","name":"Press de Banca Inclinado con Barra","nameEn":"Incline Barbell Bench Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/1.jpg"]},{"id":"decline-barbell-bench-press","name":"Press de Banca Declinado con Barra","nameEn":"Decline Barbell Bench Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Barbell_Bench_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Barbell_Bench_Press/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('chest-press-machine', 'Press de Pecho en Máquina', 'Machine Chest Press', 'Hipertrofia', 'Chest', 'Pecho / Pectoral', '["Shoulders","Triceps"]', 'Machine', 'Máquina de Palanca', 'Principiante', 'Compuesto', 'Empuje Horizontal', 'Empuje', '', '["Ajusta la altura del asiento para que los agarres queden alineados con la mitad del pecho.","Apoya la espalda firmemente contra el respaldo y toma los agarres.","Empuja hacia adelante extendiendo los brazos sin bloquear por completo los codos.","Regresa lentamente sintiendo la tensión constante en los pectorales."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Chest_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Chest_Press/1.jpg"]', '[{"id":"barbell-bench-press","name":"Press de Banca con Barra","nameEn":"Barbell Bench Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/1.jpg"]},{"id":"dumbbell-bench-press","name":"Press de Banca con Mancuernas","nameEn":"Dumbbell Bench Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/1.jpg"]},{"id":"incline-barbell-bench-press","name":"Press de Banca Inclinado con Barra","nameEn":"Incline Barbell Bench Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('cable-crossover', 'Cruces de Polea Alta', 'Cable Crossover', 'Hipertrofia', 'Chest', 'Pecho / Pectoral', '["Shoulders"]', 'Cable', 'Polea con Cable', 'Intermedio', 'Compuesto', 'Empuje Horizontal', 'Empuje', '', '["Coloca las poleas a una altura superior a tu cabeza en ambas columnas del crossover.","Sujeta los agarres D, da un paso adelante para tensar el cable y flexiona levemente las rodillas y codos.","Lleva los brazos hacia adelante y abajo en un arco de círculo encontrando tus manos al frente del abdomen bajo.","Regresa lentamente abriendo los brazos controlando el tirón del cable."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Crossover/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Crossover/1.jpg"]', '[{"id":"barbell-bench-press","name":"Press de Banca con Barra","nameEn":"Barbell Bench Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/1.jpg"]},{"id":"dumbbell-bench-press","name":"Press de Banca con Mancuernas","nameEn":"Dumbbell Bench Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/1.jpg"]},{"id":"incline-barbell-bench-press","name":"Press de Banca Inclinado con Barra","nameEn":"Incline Barbell Bench Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('low-cable-crossover', 'Cruces de Polea Baja', 'Low Cable Crossover', 'Hipertrofia', 'Chest', 'Pecho / Pectoral', '["Shoulders"]', 'Cable', 'Polea con Cable', 'Intermedio', 'Compuesto', 'Empuje Horizontal', 'Empuje', '', '["Coloca las poleas en la posición más baja de las columnas.","Toma los agarres D, da un paso adelante e inclina ligeramente el torso hacia el frente.","Lleva las manos hacia adelante y hacia arriba hasta que se junten a la altura del pecho superior.","Baja controladamente los brazos al punto de inicio."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Low_Cable_Crossover/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Low_Cable_Crossover/1.jpg"]', '[{"id":"barbell-bench-press","name":"Press de Banca con Barra","nameEn":"Barbell Bench Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/1.jpg"]},{"id":"dumbbell-bench-press","name":"Press de Banca con Mancuernas","nameEn":"Dumbbell Bench Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/1.jpg"]},{"id":"incline-barbell-bench-press","name":"Press de Banca Inclinado con Barra","nameEn":"Incline Barbell Bench Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('dumbbell-fly', 'Aperturas con Mancuernas', 'Dumbbell Fly', 'Hipertrofia', 'Chest', 'Pecho / Pectoral', '["Shoulders"]', 'Dumbbell', 'Mancuernas', 'Principiante', 'Aislamiento', 'Empuje Horizontal', 'Empuje', '', '["Acuéstate en un banco plano sosteniendo las mancuernas sobre tu pecho con las palmas mirándose.","Abre los brazos de forma lateral formando un arco amplio, doblando ligeramente los codos.","Baja hasta sentir un estiramiento cómodo en el pecho.","Contrae el pectoral para regresar las mancuernas a la posición de inicio."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Flyes/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Flyes/1.jpg"]', '[{"id":"pec-deck-fly","name":"Aperturas en Contratora (Pec Deck)","nameEn":"Pec Deck Fly","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butterfly/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butterfly/1.jpg"]},{"id":"seated-cable-flyes","name":"Cruces en Polea Sentado en Banco","nameEn":"Seated Cable Flyes","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flat_Bench_Cable_Flyes/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flat_Bench_Cable_Flyes/1.jpg"]},{"id":"barbell-bench-press","name":"Press de Banca con Barra","nameEn":"Barbell Bench Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('incline-dumbbell-fly', 'Aperturas Inclinadas con Mancuernas', 'Incline Dumbbell Fly', 'Hipertrofia', 'Chest', 'Pecho / Pectoral', '["Shoulders"]', 'Dumbbell', 'Mancuernas', 'Principiante', 'Aislamiento', 'Empuje Horizontal', 'Empuje', '', '["Acuéstate en un banco inclinado (30-45 grados) con las mancuernas en vertical sobre los hombros.","Baja las mancuernas hacia los lados manteniendo una ligera flexión de codo.","Sube contrayendo la parte alta de los pectorales."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Flyes/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Flyes/1.jpg"]', '[{"id":"pec-deck-fly","name":"Aperturas en Contratora (Pec Deck)","nameEn":"Pec Deck Fly","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butterfly/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butterfly/1.jpg"]},{"id":"seated-cable-flyes","name":"Cruces en Polea Sentado en Banco","nameEn":"Seated Cable Flyes","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flat_Bench_Cable_Flyes/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flat_Bench_Cable_Flyes/1.jpg"]},{"id":"barbell-bench-press","name":"Press de Banca con Barra","nameEn":"Barbell Bench Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('pec-deck-fly', 'Aperturas en Contratora (Pec Deck)', 'Pec Deck Fly', 'Hipertrofia', 'Chest', 'Pecho / Pectoral', '["Shoulders"]', 'Machine', 'Máquina de Palanca', 'Principiante', 'Aislamiento', 'Empuje Horizontal', 'Empuje', '', '["Siéntate con la espalda apoyada y los brazos extendidos hacia los lados tomando los agarres.","Junta los agarres en el centro contrayendo activamente el pecho.","Regresa lentamente al punto de inicio sin permitir que las pesas toquen el bloque."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butterfly/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butterfly/1.jpg"]', '[{"id":"dumbbell-fly","name":"Aperturas con Mancuernas","nameEn":"Dumbbell Fly","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Flyes/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Flyes/1.jpg"]},{"id":"incline-dumbbell-fly","name":"Aperturas Inclinadas con Mancuernas","nameEn":"Incline Dumbbell Fly","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Flyes/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Flyes/1.jpg"]},{"id":"incline-dumbbell-flyes","name":"Aperturas Inclinadas con Mancuernas","nameEn":"Incline Dumbbell Flyes","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Flyes/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Flyes/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('chest-dips', 'Fondos en Paralelas para Pecho', 'Chest Dips', 'Fuerza', 'Chest', 'Pecho / Pectoral', '["Triceps","Shoulders"]', 'Bodyweight', 'Peso Corporal', 'Avanzado', 'Compuesto', 'Empuje Horizontal', 'Empuje', '', '["Sujétate de las barras paralelas y elévate extendiendo los brazos.","Inclina el torso ligeramente hacia adelante y dobla las rodillas si es necesario.","Baja el cuerpo doblando los codos hacia afuera hasta que tus hombros estén debajo de los codos.","Empuja hacia arriba con fuerza focalizando el pectoral inferior."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dips_-_Chest_Version/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dips_-_Chest_Version/1.jpg"]', '[{"id":"barbell-bench-press","name":"Press de Banca con Barra","nameEn":"Barbell Bench Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/1.jpg"]},{"id":"dumbbell-bench-press","name":"Press de Banca con Mancuernas","nameEn":"Dumbbell Bench Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/1.jpg"]},{"id":"incline-barbell-bench-press","name":"Press de Banca Inclinado con Barra","nameEn":"Incline Barbell Bench Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('push-up', 'Flexiones de Pecho', 'Push-Up', 'Calistenia', 'Chest', 'Pecho / Pectoral', '["Shoulders","Triceps","Abs"]', 'Bodyweight', 'Peso Corporal', 'Principiante', 'Compuesto', 'Empuje Horizontal', 'Empuje', '', '["Colócate boca abajo en el suelo apoyando manos a ancho de hombros y las puntas de tus pies.","Mantén todo tu cuerpo en línea recta sin doblar la cadera.","Baja doblando los codos hacia atrás formando una flecha con tu cabeza (no codos de 90 grados).","Empuja el suelo con fuerza regresando a la plancha de inicio."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pushups/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pushups/1.jpg"]', '[{"id":"ring-pushup","name":"Flexiones en Anillas de Gimnasia","nameEn":"Gymnastic Ring Push-Up","equipment":"Rings","equipmentEs":"Anillas de Gimnasia","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Push-Up/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Push-Up/1.jpg"]},{"id":"barbell-bench-press","name":"Press de Banca con Barra","nameEn":"Barbell Bench Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/1.jpg"]},{"id":"dumbbell-bench-press","name":"Press de Banca con Mancuernas","nameEn":"Dumbbell Bench Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('decline-push-up', 'Flexiones Declina (Pies Elevados)', 'Decline Push-Up', 'Calistenia', 'Chest', 'Pecho / Pectoral', '["Shoulders","Triceps"]', 'Bodyweight', 'Peso Corporal', 'Intermedio', 'Compuesto', 'Empuje Horizontal', 'Empuje', '', '["Coloca los pies sobre un banco o superficie elevada y las manos en el suelo.","Mantén el torso y las piernas en línea recta.","Baja el pecho hacia el suelo doblando los codos.","Empuja con fuerza hacia arriba para volver a la posición inicial."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Push-Up/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Push-Up/1.jpg"]', '[{"id":"ring-pushup","name":"Flexiones en Anillas de Gimnasia","nameEn":"Gymnastic Ring Push-Up","equipment":"Rings","equipmentEs":"Anillas de Gimnasia","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Push-Up/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Push-Up/1.jpg"]},{"id":"barbell-bench-press","name":"Press de Banca con Barra","nameEn":"Barbell Bench Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/1.jpg"]},{"id":"dumbbell-bench-press","name":"Press de Banca con Mancuernas","nameEn":"Dumbbell Bench Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('deadlift', 'Peso Muerto con Barra', 'Barbell Deadlift', 'Fuerza', 'Back', 'Espalda / Dorsal', '["Hamstrings","Glutes","Forearms"]', 'Barbell', 'Barra Olímpica', 'Avanzado', 'Compuesto', 'Bisagra de Cadera', 'Tirón', '', '["Párate frente a la barra con los pies al ancho de las caderas, la barra debe cruzar la mitad del pie.","Doble la cadera inclinándote hacia abajo para tomar la barra y acomoda la espalda de forma neutra y recta.","Mantén los hombros alineados con la barra y dobla un poco las rodillas hasta que la espinilla toque la barra.","Presiona el suelo con los talones y mantén la barra pegada a ti mientras te pones de pie de manera erguida.","Bloquea arriba con fuerza sin hiperextender excesivamente la espalda baja."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Deadlift/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Deadlift/1.jpg"]', '[{"id":"sumo-deadlift","name":"Peso Muerto Sumo","nameEn":"Sumo Deadlift","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sumo_Deadlift/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sumo_Deadlift/1.jpg"]},{"id":"pull-up","name":"Dominadas Prone","nameEn":"Pull-Up","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pullups/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pullups/1.jpg"]},{"id":"behind-neck-pulldown","name":"Jalón Tras Nuca en Polea","nameEn":"Behind Neck Pulldown","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Pulldown_Behind_The_Neck/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Pulldown_Behind_The_Neck/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('sumo-deadlift', 'Peso Muerto Sumo', 'Sumo Deadlift', 'Fuerza', 'Back', 'Espalda / Dorsal', '["Glutes","Quads","Hamstrings"]', 'Barbell', 'Barra Olímpica', 'Avanzado', 'Compuesto', 'Bisagra de Cadera', 'Tirón', '', '["Adopta una postura muy ancha con las puntas de los pies apuntando hacia afuera.","Baja las caderas y sujeta la barra por el centro con los brazos dentro de las piernas.","Mantén la espalda recta e impulsa con las piernas para ponerte erguido.","Bloquea la posición superior empujando las caderas hacia la barra."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sumo_Deadlift/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sumo_Deadlift/1.jpg"]', '[{"id":"deadlift","name":"Peso Muerto con Barra","nameEn":"Barbell Deadlift","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Deadlift/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Deadlift/1.jpg"]},{"id":"pull-up","name":"Dominadas Prone","nameEn":"Pull-Up","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pullups/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pullups/1.jpg"]},{"id":"behind-neck-pulldown","name":"Jalón Tras Nuca en Polea","nameEn":"Behind Neck Pulldown","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Pulldown_Behind_The_Neck/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Pulldown_Behind_The_Neck/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('pull-up', 'Dominadas Prone', 'Pull-Up', 'Fuerza', 'Back', 'Espalda / Dorsal', '["Biceps","Shoulders","Forearms"]', 'Bodyweight', 'Peso Corporal', 'Avanzado', 'Compuesto', 'Tirón Vertical', 'Tirón', '', '["Sujétate de la barra de dominadas con un agarre prono (palmas hacia adelante) más ancho que los hombros.","Cuelga con los brazos completamente estirados y saca pecho levemente.","Tira de tu cuerpo hacia arriba retrayendo los omóplatos, llevando tu pecho hacia la barra.","Llega con la barbilla sobre la barra sin balancear las piernas.","Baja suave y controladamente hasta la posición extendida de inicio."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pullups/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pullups/1.jpg"]', '[{"id":"behind-neck-pulldown","name":"Jalón Tras Nuca en Polea","nameEn":"Behind Neck Pulldown","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Pulldown_Behind_The_Neck/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Pulldown_Behind_The_Neck/1.jpg"]},{"id":"assisted-pull-up","name":"Dominadas Asistidas en Máquina","nameEn":"Assisted Pull-Up","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Assisted_Pull-Up/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Assisted_Pull-Up/1.jpg"]},{"id":"lat-pulldown","name":"Jalón al Pecho en Polea","nameEn":"Lat Pulldown","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Lat_Pulldown/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Lat_Pulldown/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('chin-up', 'Dominadas Supinas', 'Chin-Up', 'Calistenia', 'Back', 'Espalda / Dorsal', '["Biceps","Shoulders","Forearms"]', 'Bodyweight', 'Peso Corporal', 'Intermedio', 'Compuesto', 'Tirón Vertical', 'Tirón', '', '["Sujétate de la barra con un agarre supino (palmas hacia ti) al ancho de hombros.","Cuelga con brazos estirados y tira de tu cuerpo hacia arriba.","Lleva la barbilla sobre la barra contrayendo los bíceps y dorsales.","Desciende de forma controlada."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chin-Up/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chin-Up/1.jpg"]', '[{"id":"assisted-pull-up","name":"Dominadas Asistidas en Máquina","nameEn":"Assisted Pull-Up","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Assisted_Pull-Up/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Assisted_Pull-Up/1.jpg"]},{"id":"lat-pulldown","name":"Jalón al Pecho en Polea","nameEn":"Lat Pulldown","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Lat_Pulldown/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Lat_Pulldown/1.jpg"]},{"id":"behind-neck-pulldown","name":"Jalón Tras Nuca en Polea","nameEn":"Behind Neck Pulldown","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Pulldown_Behind_The_Neck/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Pulldown_Behind_The_Neck/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('assisted-pull-up', 'Dominadas Asistidas en Máquina', 'Assisted Pull-Up', 'Hipertrofia', 'Back', 'Espalda / Dorsal', '["Biceps","Forearms"]', 'Machine', 'Máquina de Palanca', 'Principiante', 'Compuesto', 'Tirón Vertical', 'Tirón', '', '["Selecciona el peso de asistencia adecuado (a mayor peso, más fácil).","Coloca las rodillas o pies en la plataforma de asistencia.","Sujeta las barras superiores y realiza el movimiento de dominada controlando el descenso."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Assisted_Pull-Up/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Assisted_Pull-Up/1.jpg"]', '[{"id":"lat-pulldown","name":"Jalón al Pecho en Polea","nameEn":"Lat Pulldown","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Lat_Pulldown/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Lat_Pulldown/1.jpg"]},{"id":"pull-up","name":"Dominadas Prone","nameEn":"Pull-Up","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pullups/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pullups/1.jpg"]},{"id":"chin-up","name":"Dominadas Supinas","nameEn":"Chin-Up","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chin-Up/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chin-Up/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('lat-pulldown', 'Jalón al Pecho en Polea', 'Lat Pulldown', 'Hipertrofia', 'Back', 'Espalda / Dorsal', '["Biceps","Forearms"]', 'Cable', 'Polea con Cable', 'Principiante', 'Compuesto', 'Tirón Vertical', 'Tirón', '', '["Siéntate en la máquina ajustando el colchón a tus muslos para que no te levantes.","Sujeta la barra con agarre amplio prono y sostén con los brazos totalmente estirados.","Inclina ligeramente el torso hacia atrás y conduce los codos hacia abajo bajando la barra a tu pecho alto.","Concentra la fuerza en juntar tus codos a los costados antes que jalar con los puños.","Extiende lentamente de regreso estirando los dorsales por completo."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Lat_Pulldown/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Lat_Pulldown/1.jpg"]', '[{"id":"assisted-pull-up","name":"Dominadas Asistidas en Máquina","nameEn":"Assisted Pull-Up","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Assisted_Pull-Up/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Assisted_Pull-Up/1.jpg"]},{"id":"pull-up","name":"Dominadas Prone","nameEn":"Pull-Up","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pullups/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pullups/1.jpg"]},{"id":"chin-up","name":"Dominadas Supinas","nameEn":"Chin-Up","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chin-Up/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chin-Up/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('behind-neck-pulldown', 'Jalón Tras Nuca en Polea', 'Behind Neck Pulldown', 'Fuerza', 'Back', 'Espalda / Dorsal', '["Biceps","Shoulders"]', 'Cable', 'Polea con Cable', 'Avanzado', 'Compuesto', 'Tirón Vertical', 'Tirón', '', '["Siéntate en la máquina de jalones con agarre amplio.","Mantén el torso erguido y baja la barra lentamente por detrás de la cabeza hasta la nuca.","Evita movimientos bruscos para no tensionar los rotadores del hombro.","Sube la barra controlando la fase excéntrica."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Pulldown_Behind_The_Neck/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Pulldown_Behind_The_Neck/1.jpg"]', '[{"id":"pull-up","name":"Dominadas Prone","nameEn":"Pull-Up","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pullups/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pullups/1.jpg"]},{"id":"chin-up","name":"Dominadas Supinas","nameEn":"Chin-Up","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chin-Up/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chin-Up/1.jpg"]},{"id":"assisted-pull-up","name":"Dominadas Asistidas en Máquina","nameEn":"Assisted Pull-Up","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Assisted_Pull-Up/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Assisted_Pull-Up/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('barbell-row', 'Remo con Barra', 'Barbell Row', 'Hipertrofia', 'Back', 'Espalda / Dorsal', '["Biceps","Forearms"]', 'Barbell', 'Barra Olímpica', 'Intermedio', 'Compuesto', 'Tirón Horizontal', 'Tirón', '', '["Sostén una barra cargada con agarre prono y colócate de pie.","Flexiona la cadera enviando los glúteos atrás y la espalda perfectamente neutra en un ángulo de casi 45 grados.","Jala la barra verticalmente hacia tu ombligo levantando los codos por encima del torso.","Mantén los codos pegados a ti y aprieta la espalda al final.","Baja la barra de vuelta de forma extendida y controlada."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/1.jpg"]', '[{"id":"t-bar-row","name":"Remo en Barra T","nameEn":"T-Bar Row","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/1.jpg"]},{"id":"dumbbell-single-row","name":"Remo a una Mano con Mancuerna","nameEn":"Dumbbell Single-Arm Row","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/1.jpg"]},{"id":"seated-cable-row","name":"Remo Sentado en Polea con Agarre Gironda","nameEn":"Seated Cable Row","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Cable_Rows/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Cable_Rows/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('t-bar-row', 'Remo en Barra T', 'T-Bar Row', 'Hipertrofia', 'Back', 'Espalda / Dorsal', '["Biceps","Forearms"]', 'Machine', 'Máquina de Palanca', 'Intermedio', 'Compuesto', 'Tirón Horizontal', 'Tirón', '', '["Colócate en la plataforma de la barra T y flexiona las rodillas y cadera.","Toma las manijas con un agarre neutro o prono.","Manteniendo la espalda recta, jala el peso hacia el pecho contrayendo la espalda media.","Baja lentamente el peso extendiendo los brazos."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/1.jpg"]', '[{"id":"barbell-row","name":"Remo con Barra","nameEn":"Barbell Row","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/1.jpg"]},{"id":"dumbbell-single-row","name":"Remo a una Mano con Mancuerna","nameEn":"Dumbbell Single-Arm Row","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/1.jpg"]},{"id":"seated-cable-row","name":"Remo Sentado en Polea con Agarre Gironda","nameEn":"Seated Cable Row","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Cable_Rows/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Cable_Rows/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('dumbbell-single-row', 'Remo a una Mano con Mancuerna', 'Dumbbell Single-Arm Row', 'Hipertrofia', 'Back', 'Espalda / Dorsal', '["Biceps","Forearms"]', 'Dumbbell', 'Mancuernas', 'Principiante', 'Compuesto', 'Tirón Horizontal', 'Tirón', '', '["Apoya una rodilla y la mano del mismo lado sobre un banco plano.","Mantén la espalda paralela al suelo y sujeta una mancuerna con el brazo libre extendido.","Jala la mancuerna hacia tu cadera, elevando el codo hacia el techo y manteniendo el brazo rozando tu costado.","Baja con lentitud estirando el hombro sin rotar la columna."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/1.jpg"]', '[{"id":"barbell-row","name":"Remo con Barra","nameEn":"Barbell Row","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/1.jpg"]},{"id":"t-bar-row","name":"Remo en Barra T","nameEn":"T-Bar Row","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/1.jpg"]},{"id":"seated-cable-row","name":"Remo Sentado en Polea con Agarre Gironda","nameEn":"Seated Cable Row","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Cable_Rows/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Cable_Rows/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('seated-cable-row', 'Remo Sentado en Polea con Agarre Gironda', 'Seated Cable Row', 'Hipertrofia', 'Back', 'Espalda / Dorsal', '["Biceps","Forearms"]', 'Cable', 'Polea con Cable', 'Principiante', 'Compuesto', 'Tirón Horizontal', 'Tirón', '', '["Siéntate con los pies apoyados e inclínate para tomar el agarre estrecho.","Enderézate con el torso perpendicular al suelo y los brazos extendidos.","Jala el agarre hacia tu abdomen bajo retrayendo la espalda media y flexionando codos.","Regresa extendiendo los brazos sin redondear la columna."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Cable_Rows/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Cable_Rows/1.jpg"]', '[{"id":"barbell-row","name":"Remo con Barra","nameEn":"Barbell Row","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/1.jpg"]},{"id":"t-bar-row","name":"Remo en Barra T","nameEn":"T-Bar Row","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/1.jpg"]},{"id":"dumbbell-single-row","name":"Remo a una Mano con Mancuerna","nameEn":"Dumbbell Single-Arm Row","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('chest-supported-dumbbell-row', 'Remo Apoyado en Banco con Mancuernas', 'Chest-Supported Dumbbell Row', 'Hipertrofia', 'Back', 'Espalda / Dorsal', '["Biceps","Shoulders"]', 'Dumbbell', 'Mancuernas', 'Principiante', 'Compuesto', 'Tirón Horizontal', 'Tirón', '', '["Coloca un banco a unos 30 grados de inclinación.","Acuéstate boca abajo apoyando el pecho contra el respaldo.","Toma una mancuerna en cada mano y déjalas colgar estiradas.","Jala los codos hacia arriba y atrás contrayendo la espalda sin despegar el pecho."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Incline_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Incline_Row/1.jpg"]', '[{"id":"barbell-row","name":"Remo con Barra","nameEn":"Barbell Row","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/1.jpg"]},{"id":"t-bar-row","name":"Remo en Barra T","nameEn":"T-Bar Row","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/1.jpg"]},{"id":"seated-cable-row","name":"Remo Sentado en Polea con Agarre Gironda","nameEn":"Seated Cable Row","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Cable_Rows/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Cable_Rows/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('straight-arm-pulldown', 'Pullover en Polea con Brazos Rectos', 'Straight Arm Pulldown', 'Hipertrofia', 'Back', 'Espalda / Dorsal', '["Triceps","Chest"]', 'Cable', 'Polea con Cable', 'Intermedio', 'Compuesto', 'Tirón Horizontal', 'Tirón', '', '["Párate frente a la polea alta con una barra recta.","Toma la barra a la altura de los hombros y da un paso atrás para estirar el cable.","Inclinando un poco el torso hacia adelante, jala la barra con los brazos casi rectos hasta los muslos.","Regresa lentamente al punto de inicio sintiendo el estiramiento del dorsal."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rope_Straight-Arm_Pulldown/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rope_Straight-Arm_Pulldown/1.jpg"]', '[{"id":"barbell-row","name":"Remo con Barra","nameEn":"Barbell Row","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/1.jpg"]},{"id":"t-bar-row","name":"Remo en Barra T","nameEn":"T-Bar Row","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/1.jpg"]},{"id":"dumbbell-single-row","name":"Remo a una Mano con Mancuerna","nameEn":"Dumbbell Single-Arm Row","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('barbell-pullover', 'Pullover con Barra', 'Barbell Pullover', 'Hipertrofia', 'Back', 'Espalda / Dorsal', '["Chest","Triceps"]', 'Barbell', 'Barra Olímpica', 'Intermedio', 'Compuesto', 'Tirón Horizontal', 'Tirón', '', '["Acuéstate a lo largo de un banco plano sosteniendo la barra directamente sobre tu pecho.","Manteniendo los codos ligeramente flexionados, baja la barra detrás de la cabeza.","Lleva la barra de regreso sobre el pecho contrayendo los dorsales y pectorales."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent-Arm_Barbell_Pullover/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent-Arm_Barbell_Pullover/1.jpg"]', '[{"id":"t-bar-row","name":"Remo en Barra T","nameEn":"T-Bar Row","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/1.jpg"]},{"id":"dumbbell-single-row","name":"Remo a una Mano con Mancuerna","nameEn":"Dumbbell Single-Arm Row","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/1.jpg"]},{"id":"seated-cable-row","name":"Remo Sentado en Polea con Agarre Gironda","nameEn":"Seated Cable Row","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Cable_Rows/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Cable_Rows/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('back-hyperextension', 'Hiperextensiones Lumbares', 'Back Hyperextension', 'Hipertrofia', 'Back', 'Espalda / Dorsal', '["Glutes","Hamstrings"]', 'None', 'Sin Equipamiento', 'Principiante', 'Compuesto', 'Tirón Horizontal', 'Core', '', '["Colócate en el banco de hiperextensiones con los tobillos asegurados.","Flexiona la cadera bajando el torso de forma controlada con la espalda recta.","Contrae la espalda baja y glúteos para levantar el torso hasta alinearlo con tus piernas."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hyperextensions_Back_Extensions/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hyperextensions_Back_Extensions/1.jpg"]', '[{"id":"barbell-row","name":"Remo con Barra","nameEn":"Barbell Row","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/1.jpg"]},{"id":"t-bar-row","name":"Remo en Barra T","nameEn":"T-Bar Row","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/1.jpg"]},{"id":"dumbbell-single-row","name":"Remo a una Mano con Mancuerna","nameEn":"Dumbbell Single-Arm Row","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('barbell-shrug', 'Encogimientos de Hombros con Barra', 'Barbell Shrug', 'Hipertrofia', 'Back', 'Espalda / Dorsal', '["Shoulders"]', 'Barbell', 'Barra Olímpica', 'Principiante', 'Compuesto', 'Empuje Vertical', 'Tirón', '', '["Párate erguido sosteniendo la barra delante de los muslos con agarre prono.","Eleva los hombros verticalmente hacia las orejas lo más alto posible.","Sostén un segundo arriba y baja controladamente."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Shrug/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Shrug/1.jpg"]', '[{"id":"assisted-pull-up","name":"Dominadas Asistidas en Máquina","nameEn":"Assisted Pull-Up","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Assisted_Pull-Up/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Assisted_Pull-Up/1.jpg"]},{"id":"lat-pulldown","name":"Jalón al Pecho en Polea","nameEn":"Lat Pulldown","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Lat_Pulldown/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Lat_Pulldown/1.jpg"]},{"id":"t-bar-row","name":"Remo en Barra T","nameEn":"T-Bar Row","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('dumbbell-shrug', 'Encogimientos con Mancuernas', 'Dumbbell Shrug', 'Hipertrofia', 'Back', 'Espalda / Dorsal', '["Shoulders"]', 'Dumbbell', 'Mancuernas', 'Principiante', 'Compuesto', 'Tirón Horizontal', 'Tirón', '', '["Sostén una mancuerna a cada lado de tu torso.","Eleva los hombros hacia arriba sin doblar los codos y sin rotar los hombros hacia atrás.","Baja el peso a la posición inicial."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Shrug/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Shrug/1.jpg"]', '[{"id":"barbell-row","name":"Remo con Barra","nameEn":"Barbell Row","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/1.jpg"]},{"id":"t-bar-row","name":"Remo en Barra T","nameEn":"T-Bar Row","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/1.jpg"]},{"id":"seated-cable-row","name":"Remo Sentado en Polea con Agarre Gironda","nameEn":"Seated Cable Row","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Cable_Rows/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Cable_Rows/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('overhead-press', 'Press Militar con Barra', 'Barbell Overhead Press', 'Fuerza', 'Shoulders', 'Hombros / Deltoides', '["Triceps","Abs"]', 'Barbell', 'Barra Olímpica', 'Avanzado', 'Compuesto', 'Empuje Vertical', 'Empuje', '', '["Párate con los pies al ancho de tus caderas y descansa la barra sobre tus clavículas o pecho alto.","Aprieta fuerte tus glúteos y tu abdomen para dar estabilidad a tu espalda baja.","Empuja la barra rectamente hacia el techo pasando cerca de tu cara y bloqueando suave arriba.","Pasa la cabeza levemente hacia adelante una vez la barra libre tu frente.","Baja controladamente de vuelta a tus clavículas."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Military_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Military_Press/1.jpg"]', '[{"id":"dumbbell-shoulder-press","name":"Press de Hombro con Mancuernas","nameEn":"Dumbbell Shoulder Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Shoulder_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Shoulder_Press/1.jpg"]},{"id":"arnold-press","name":"Press Arnold con Mancuernas","nameEn":"Arnold Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Arnold_Dumbbell_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Arnold_Dumbbell_Press/1.jpg"]},{"id":"rear-delt-fly","name":"Pájaros con Mancuernas (Hombro Posterior)","nameEn":"Dumbbell Rear Delt Fly","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Bent-Over_Rear_Delt_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Bent-Over_Rear_Delt_Raise/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('seated-barbell-press', 'Press Militar Sentado con Barra', 'Seated Barbell Press', 'Hipertrofia', 'Shoulders', 'Hombros / Deltoides', '["Triceps"]', 'Barbell', 'Barra Olímpica', 'Intermedio', 'Compuesto', 'Empuje Vertical', 'Empuje', '', '["Siéntate en un banco con soporte para barra.","Toma la barra un poco más ancha que los hombros y sácala del soporte.","Bájala lentamente hasta la barbilla y empuja verticalmente."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Barbell_Military_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Barbell_Military_Press/1.jpg"]', '[{"id":"dumbbell-shoulder-press","name":"Press de Hombro con Mancuernas","nameEn":"Dumbbell Shoulder Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Shoulder_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Shoulder_Press/1.jpg"]},{"id":"arnold-press","name":"Press Arnold con Mancuernas","nameEn":"Arnold Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Arnold_Dumbbell_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Arnold_Dumbbell_Press/1.jpg"]},{"id":"rear-delt-fly","name":"Pájaros con Mancuernas (Hombro Posterior)","nameEn":"Dumbbell Rear Delt Fly","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Bent-Over_Rear_Delt_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Bent-Over_Rear_Delt_Raise/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('dumbbell-shoulder-press', 'Press de Hombro con Mancuernas', 'Dumbbell Shoulder Press', 'Hipertrofia', 'Shoulders', 'Hombros / Deltoides', '["Triceps"]', 'Dumbbell', 'Mancuernas', 'Principiante', 'Compuesto', 'Empuje Vertical', 'Empuje', '', '["Siéntate en un banco con respaldo vertical casi en 90 grados.","Lleva las mancuernas sobre tus hombros con los codos apuntando en diagonal (no rectos a los lados).","Empuja el peso verticalmente hacia arriba hasta estirar por completo los brazos.","Baja lentamente hasta que tus manos estén a la altura de las orejas."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Shoulder_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Shoulder_Press/1.jpg"]', '[{"id":"seated-barbell-press","name":"Press Militar Sentado con Barra","nameEn":"Seated Barbell Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Barbell_Military_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Barbell_Military_Press/1.jpg"]},{"id":"face-pull","name":"Face Pull con Cuerda en Polea","nameEn":"Cable Face Pull","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Face_Pull/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Face_Pull/1.jpg"]},{"id":"upright-row","name":"Remo al Mentón con Barra","nameEn":"Barbell Upright Row","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upright_Barbell_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upright_Barbell_Row/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('arnold-press', 'Press Arnold con Mancuernas', 'Arnold Press', 'Hipertrofia', 'Shoulders', 'Hombros / Deltoides', '["Triceps"]', 'Dumbbell', 'Mancuernas', 'Intermedio', 'Compuesto', 'Empuje Vertical', 'Empuje', '', '["Siéntate en un banco y sostén las mancuernas al nivel del pecho con palmas mirando hacia ti.","Empuja las mancuernas hacia arriba mientras giras las muñecas 180 grados.","En el tope del movimiento, las palmas deben mirar hacia adelante.","Baja el peso girando las muñecas a la posición inicial."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Arnold_Dumbbell_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Arnold_Dumbbell_Press/1.jpg"]', '[{"id":"seated-barbell-press","name":"Press Militar Sentado con Barra","nameEn":"Seated Barbell Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Barbell_Military_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Barbell_Military_Press/1.jpg"]},{"id":"face-pull","name":"Face Pull con Cuerda en Polea","nameEn":"Cable Face Pull","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Face_Pull/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Face_Pull/1.jpg"]},{"id":"upright-row","name":"Remo al Mentón con Barra","nameEn":"Barbell Upright Row","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upright_Barbell_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upright_Barbell_Row/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('lateral-raise', 'Elevaciones Laterales con Mancuernas', 'Dumbbell Lateral Raise', 'Hipertrofia', 'Shoulders', 'Hombros / Deltoides', '[]', 'Dumbbell', 'Mancuernas', 'Principiante', 'Aislamiento', 'Empuje Vertical', 'Empuje', '', '["Párate erguido con una mancuerna en cada mano colgando a los lados.","Con los codos ligeramente flexionados, eleva los brazos hacia los costados en un plano levemente escapular (30 grados adelante).","Sube hasta la altura de tus hombros en paralelo al suelo de tal manera que el dedo meñique apunte levemente arriba.","Baja lentamente sintiendo la tensión en el deltoides lateral."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lateral_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lateral_Raise/1.jpg"]', '[{"id":"cable-lateral-raise","name":"Elevaciones Laterales en Polea","nameEn":"Cable Lateral Raise","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Seated_Lateral_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Seated_Lateral_Raise/1.jpg"]},{"id":"machine-lateral-raise","name":"Elevaciones Laterales en Máquina","nameEn":"Machine Lateral Raise","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lateral_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lateral_Raise/1.jpg"]},{"id":"front-plate-raise","name":"Elevaciones Frontales con Disco","nameEn":"Front Plate Raise","equipment":"None","equipmentEs":"Sin Equipamiento","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Plate_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Plate_Raise/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('cable-lateral-raise', 'Elevaciones Laterales en Polea', 'Cable Lateral Raise', 'Hipertrofia', 'Shoulders', 'Hombros / Deltoides', '[]', 'Cable', 'Polea con Cable', 'Intermedio', 'Aislamiento', 'Empuje Vertical', 'Empuje', '', '["Párate de lado a la polea baja, sostén el agarre D con el brazo opuesto.","Eleva el cable lateralmente cruzando el cuerpo hasta la altura del hombro.","Regresa lentamente al punto de inicio."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Seated_Lateral_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Seated_Lateral_Raise/1.jpg"]', '[{"id":"lateral-raise","name":"Elevaciones Laterales con Mancuernas","nameEn":"Dumbbell Lateral Raise","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lateral_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lateral_Raise/1.jpg"]},{"id":"machine-lateral-raise","name":"Elevaciones Laterales en Máquina","nameEn":"Machine Lateral Raise","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lateral_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lateral_Raise/1.jpg"]},{"id":"front-dumbbell-raise","name":"Elevaciones Frontales con Mancuernas","nameEn":"Front Dumbbell Raise","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Dumbbell_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Dumbbell_Raise/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('machine-lateral-raise', 'Elevaciones Laterales en Máquina', 'Machine Lateral Raise', 'Hipertrofia', 'Shoulders', 'Hombros / Deltoides', '[]', 'Machine', 'Máquina de Palanca', 'Principiante', 'Aislamiento', 'Empuje Vertical', 'Empuje', '', '["Siéntate en la máquina apoyando los brazos contra las almohadillas.","Eleva los codos hacia afuera contrayendo los hombros.","Baja controladamente resistiendo el peso."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lateral_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lateral_Raise/1.jpg"]', '[{"id":"lateral-raise","name":"Elevaciones Laterales con Mancuernas","nameEn":"Dumbbell Lateral Raise","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lateral_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lateral_Raise/1.jpg"]},{"id":"cable-lateral-raise","name":"Elevaciones Laterales en Polea","nameEn":"Cable Lateral Raise","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Seated_Lateral_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Seated_Lateral_Raise/1.jpg"]},{"id":"front-dumbbell-raise","name":"Elevaciones Frontales con Mancuernas","nameEn":"Front Dumbbell Raise","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Dumbbell_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Dumbbell_Raise/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('front-dumbbell-raise', 'Elevaciones Frontales con Mancuernas', 'Front Dumbbell Raise', 'Hipertrofia', 'Shoulders', 'Hombros / Deltoides', '[]', 'Dumbbell', 'Mancuernas', 'Principiante', 'Aislamiento', 'Empuje Vertical', 'Empuje', '', '["Sostén las mancuernas frente a tus muslos con agarre prono.","Eleva una mancuerna hacia adelante hasta la altura de los ojos de forma controlada.","Baja el peso e intercambia el brazo o elévalos juntos."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Dumbbell_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Dumbbell_Raise/1.jpg"]', '[{"id":"cable-lateral-raise","name":"Elevaciones Laterales en Polea","nameEn":"Cable Lateral Raise","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Seated_Lateral_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Seated_Lateral_Raise/1.jpg"]},{"id":"machine-lateral-raise","name":"Elevaciones Laterales en Máquina","nameEn":"Machine Lateral Raise","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lateral_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lateral_Raise/1.jpg"]},{"id":"front-plate-raise","name":"Elevaciones Frontales con Disco","nameEn":"Front Plate Raise","equipment":"None","equipmentEs":"Sin Equipamiento","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Plate_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Plate_Raise/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('front-plate-raise', 'Elevaciones Frontales con Disco', 'Front Plate Raise', 'Hipertrofia', 'Shoulders', 'Hombros / Deltoides', '[]', 'None', 'Sin Equipamiento', 'Principiante', 'Aislamiento', 'Empuje Vertical', 'Empuje', '', '["Sostén un disco de peso con ambas manos a los lados del disco.","Eleva el disco hacia adelante a la altura del pecho superior.","Baja controladamente hacia los muslos."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Plate_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Plate_Raise/1.jpg"]', '[{"id":"lateral-raise","name":"Elevaciones Laterales con Mancuernas","nameEn":"Dumbbell Lateral Raise","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lateral_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lateral_Raise/1.jpg"]},{"id":"cable-lateral-raise","name":"Elevaciones Laterales en Polea","nameEn":"Cable Lateral Raise","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Seated_Lateral_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Seated_Lateral_Raise/1.jpg"]},{"id":"machine-lateral-raise","name":"Elevaciones Laterales en Máquina","nameEn":"Machine Lateral Raise","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lateral_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lateral_Raise/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('rear-delt-fly', 'Pájaros con Mancuernas (Hombro Posterior)', 'Dumbbell Rear Delt Fly', 'Hipertrofia', 'Shoulders', 'Hombros / Deltoides', '["Back"]', 'Dumbbell', 'Mancuernas', 'Principiante', 'Compuesto', 'Empuje Vertical', 'Tirón', '', '["Inclinando el torso hacia adelante casi paralelo al suelo doblando rodillas.","Sostén las mancuernas colgando abajo.","Eleva las mancuernas hacia los lados retrayendo el deltoides posterior.","Baja el peso controladamente."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Bent-Over_Rear_Delt_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Bent-Over_Rear_Delt_Raise/1.jpg"]', '[{"id":"seated-barbell-press","name":"Press Militar Sentado con Barra","nameEn":"Seated Barbell Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Barbell_Military_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Barbell_Military_Press/1.jpg"]},{"id":"face-pull","name":"Face Pull con Cuerda en Polea","nameEn":"Cable Face Pull","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Face_Pull/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Face_Pull/1.jpg"]},{"id":"upright-row","name":"Remo al Mentón con Barra","nameEn":"Barbell Upright Row","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upright_Barbell_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upright_Barbell_Row/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('reverse-pec-deck', 'Aperturas Inversas en Máquina', 'Reverse Pec Deck Fly', 'Hipertrofia', 'Shoulders', 'Hombros / Deltoides', '["Back"]', 'Machine', 'Máquina de Palanca', 'Principiante', 'Aislamiento', 'Empuje Vertical', 'Tirón', '', '["Siéntate mirando hacia la máquina contratora.","Toma los agarres a nivel de los hombros con los codos ligeramente flexionados.","Jala hacia atrás abriendo los brazos hasta contraer el deltoides posterior."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Machine_Flyes/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Machine_Flyes/1.jpg"]', '[{"id":"lateral-raise","name":"Elevaciones Laterales con Mancuernas","nameEn":"Dumbbell Lateral Raise","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lateral_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lateral_Raise/1.jpg"]},{"id":"cable-lateral-raise","name":"Elevaciones Laterales en Polea","nameEn":"Cable Lateral Raise","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Seated_Lateral_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Seated_Lateral_Raise/1.jpg"]},{"id":"front-dumbbell-raise","name":"Elevaciones Frontales con Mancuernas","nameEn":"Front Dumbbell Raise","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Dumbbell_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Dumbbell_Raise/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('face-pull', 'Face Pull con Cuerda en Polea', 'Cable Face Pull', 'Hipertrofia', 'Shoulders', 'Hombros / Deltoides', '["Back"]', 'Cable', 'Polea con Cable', 'Intermedio', 'Compuesto', 'Empuje Vertical', 'Tirón', '', '["Ajusta la polea a la altura del rostro superior y conecta la soga.","Toma la soga con pulgares apuntando hacia ti y da dos pasos atrás.","Jala la soga hacia la frente separando los extremos de la cuerda al nivel de tus orejas.","Aprieta el deltoides posterior e infraespinoso, y regresa despacio."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Face_Pull/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Face_Pull/1.jpg"]', '[{"id":"seated-barbell-press","name":"Press Militar Sentado con Barra","nameEn":"Seated Barbell Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Barbell_Military_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Barbell_Military_Press/1.jpg"]},{"id":"dumbbell-shoulder-press","name":"Press de Hombro con Mancuernas","nameEn":"Dumbbell Shoulder Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Shoulder_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Shoulder_Press/1.jpg"]},{"id":"arnold-press","name":"Press Arnold con Mancuernas","nameEn":"Arnold Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Arnold_Dumbbell_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Arnold_Dumbbell_Press/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('upright-row', 'Remo al Mentón con Barra', 'Barbell Upright Row', 'Hipertrofia', 'Shoulders', 'Hombros / Deltoides', '["Back"]', 'Barbell', 'Barra Olímpica', 'Intermedio', 'Compuesto', 'Empuje Vertical', 'Tirón', '', '["Párate erguido sosteniendo la barra delante de ti con agarre estrecho.","Jala la barra verticalmente hacia tu mentón elevando los codos por encima de la barra.","Mantén la barra muy pegada al cuerpo durante el movimiento.","Baja lentamente."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upright_Barbell_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upright_Barbell_Row/1.jpg"]', '[{"id":"dumbbell-shoulder-press","name":"Press de Hombro con Mancuernas","nameEn":"Dumbbell Shoulder Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Shoulder_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Shoulder_Press/1.jpg"]},{"id":"arnold-press","name":"Press Arnold con Mancuernas","nameEn":"Arnold Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Arnold_Dumbbell_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Arnold_Dumbbell_Press/1.jpg"]},{"id":"rear-delt-fly","name":"Pájaros con Mancuernas (Hombro Posterior)","nameEn":"Dumbbell Rear Delt Fly","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Bent-Over_Rear_Delt_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Bent-Over_Rear_Delt_Raise/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('barbell-curl', 'Curl de Bíceps con Barra EZ', 'Barbell Curl', 'Hipertrofia', 'Biceps', 'Bíceps', '["Forearms"]', 'Barbell', 'Barra Olímpica', 'Principiante', 'Aislamiento', 'Tirón Vertical', 'Tirón', '', '["Sujeta la barra curva EZ frente a ti con agarre supino (palmas bocarriba) ancho de hombros.","Mantén los codos pegados a tus costados y rígidos.","Contrae los bíceps trayendo la barra hacia el pecho sin balancear la espalda.","Aprieta arriba un segundo y desciende estirando suavemente el codo."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curl/1.jpg"]', '[{"id":"dumbbell-curl","name":"Curl de Bíceps alterno con Mancuernas","nameEn":"Dumbbell Curl","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Biceps","primaryMuscleEs":"Bíceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bicep_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bicep_Curl/1.jpg"]},{"id":"incline-dumbbell-curl","name":"Curl Inclinado con Mancuernas","nameEn":"Incline Dumbbell Curl","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Biceps","primaryMuscleEs":"Bíceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Curl/1.jpg"]},{"id":"hammer-curl","name":"Curl de Bíceps Martillo","nameEn":"Hammer Curl","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Biceps","primaryMuscleEs":"Bíceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hammer_Curls/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hammer_Curls/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('dumbbell-curl', 'Curl de Bíceps alterno con Mancuernas', 'Dumbbell Curl', 'Hipertrofia', 'Biceps', 'Bíceps', '["Forearms"]', 'Dumbbell', 'Mancuernas', 'Principiante', 'Aislamiento', 'Tirón Vertical', 'Tirón', '', '["Párate o siéntate con una mancuerna a cada lado.","Eleva el peso flexionando el codo y girando la muñeca hacia arriba (supinando) en el medio del recorrido.","Baja controladamente y alterna de brazo."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bicep_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bicep_Curl/1.jpg"]', '[{"id":"barbell-curl","name":"Curl de Bíceps con Barra EZ","nameEn":"Barbell Curl","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Biceps","primaryMuscleEs":"Bíceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curl/1.jpg"]},{"id":"preacher-curl","name":"Curl Predicador en Banco Scott","nameEn":"Preacher Curl","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Biceps","primaryMuscleEs":"Bíceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Preacher_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Preacher_Curl/1.jpg"]},{"id":"cable-curl","name":"Curl de Bíceps en Polea","nameEn":"Cable Bicep Curl","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Biceps","primaryMuscleEs":"Bíceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Biceps_Cable_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Biceps_Cable_Curl/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('incline-dumbbell-curl', 'Curl Inclinado con Mancuernas', 'Incline Dumbbell Curl', 'Hipertrofia', 'Biceps', 'Bíceps', '["Forearms"]', 'Dumbbell', 'Mancuernas', 'Intermedio', 'Aislamiento', 'Tirón Vertical', 'Tirón', '', '["Siéntate en un banco inclinado a unos 45 grados sosteniendo las mancuernas colgadas.","Flexiona los codos manteniendo los brazos detrás del torso para enfatizar la cabeza larga del bíceps.","Baja extendiendo completamente."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Curl/1.jpg"]', '[{"id":"barbell-curl","name":"Curl de Bíceps con Barra EZ","nameEn":"Barbell Curl","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Biceps","primaryMuscleEs":"Bíceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curl/1.jpg"]},{"id":"preacher-curl","name":"Curl Predicador en Banco Scott","nameEn":"Preacher Curl","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Biceps","primaryMuscleEs":"Bíceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Preacher_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Preacher_Curl/1.jpg"]},{"id":"cable-curl","name":"Curl de Bíceps en Polea","nameEn":"Cable Bicep Curl","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Biceps","primaryMuscleEs":"Bíceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Biceps_Cable_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Biceps_Cable_Curl/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('hammer-curl', 'Curl de Bíceps Martillo', 'Hammer Curl', 'Hipertrofia', 'Biceps', 'Bíceps', '["Forearms"]', 'Dumbbell', 'Mancuernas', 'Principiante', 'Aislamiento', 'Tirón Vertical', 'Tirón', '', '["Sostén un par de mancuernas a los lados de tu torso con agarre neutro (las palmas se miran cara a cara).","Sube la mancuerna verticalmente doblando el codo sin girar la muñeca.","Asegúrate de no usar impulso en la parte baja del movimiento.","Desciende con control absoluto de los flexores de codo."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hammer_Curls/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hammer_Curls/1.jpg"]', '[{"id":"barbell-curl","name":"Curl de Bíceps con Barra EZ","nameEn":"Barbell Curl","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Biceps","primaryMuscleEs":"Bíceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curl/1.jpg"]},{"id":"preacher-curl","name":"Curl Predicador en Banco Scott","nameEn":"Preacher Curl","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Biceps","primaryMuscleEs":"Bíceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Preacher_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Preacher_Curl/1.jpg"]},{"id":"cable-curl","name":"Curl de Bíceps en Polea","nameEn":"Cable Bicep Curl","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Biceps","primaryMuscleEs":"Bíceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Biceps_Cable_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Biceps_Cable_Curl/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('preacher-curl', 'Curl Predicador en Banco Scott', 'Preacher Curl', 'Hipertrofia', 'Biceps', 'Bíceps', '["Forearms"]', 'Barbell', 'Barra Olímpica', 'Principiante', 'Aislamiento', 'Tirón Vertical', 'Tirón', '', '["Siéntate en el banco predicador y apoya la parte posterior de tus brazos firmemente contra el colchón.","Toma la barra EZ y flexiona los codos para llevar el peso arriba sin separar los brazos de la almohadilla.","Baja controladamente estirando casi por completo los codos."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Preacher_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Preacher_Curl/1.jpg"]', '[{"id":"dumbbell-curl","name":"Curl de Bíceps alterno con Mancuernas","nameEn":"Dumbbell Curl","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Biceps","primaryMuscleEs":"Bíceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bicep_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bicep_Curl/1.jpg"]},{"id":"incline-dumbbell-curl","name":"Curl Inclinado con Mancuernas","nameEn":"Incline Dumbbell Curl","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Biceps","primaryMuscleEs":"Bíceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Curl/1.jpg"]},{"id":"hammer-curl","name":"Curl de Bíceps Martillo","nameEn":"Hammer Curl","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Biceps","primaryMuscleEs":"Bíceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hammer_Curls/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hammer_Curls/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('concentration-curl', 'Curl de Concentración con Mancuerna', 'Concentration Curl', 'Hipertrofia', 'Biceps', 'Bíceps', '[]', 'Dumbbell', 'Mancuernas', 'Principiante', 'Aislamiento', 'Tirón Vertical', 'Tirón', '', '["Siéntate en un banco, apoya el codo contra la cara interna de tu muslo del mismo lado.","Flexiona el codo levantando la mancuerna de forma aislada hacia tu cara.","Baja de vuelta controladamente."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Concentration_Curls/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Concentration_Curls/1.jpg"]', '[{"id":"barbell-curl","name":"Curl de Bíceps con Barra EZ","nameEn":"Barbell Curl","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Biceps","primaryMuscleEs":"Bíceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curl/1.jpg"]},{"id":"preacher-curl","name":"Curl Predicador en Banco Scott","nameEn":"Preacher Curl","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Biceps","primaryMuscleEs":"Bíceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Preacher_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Preacher_Curl/1.jpg"]},{"id":"cable-curl","name":"Curl de Bíceps en Polea","nameEn":"Cable Bicep Curl","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Biceps","primaryMuscleEs":"Bíceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Biceps_Cable_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Biceps_Cable_Curl/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('cable-curl', 'Curl de Bíceps en Polea', 'Cable Bicep Curl', 'Hipertrofia', 'Biceps', 'Bíceps', '["Forearms"]', 'Cable', 'Polea con Cable', 'Principiante', 'Aislamiento', 'Tirón Vertical', 'Tirón', '', '["Párate frente a la polea baja con barra de agarre.","Toma la barra con palmas hacia arriba y flexiona los codos contrayendo bíceps.","Baja resistiendo la tensión constante del cable."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Biceps_Cable_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Biceps_Cable_Curl/1.jpg"]', '[{"id":"barbell-curl","name":"Curl de Bíceps con Barra EZ","nameEn":"Barbell Curl","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Biceps","primaryMuscleEs":"Bíceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curl/1.jpg"]},{"id":"dumbbell-curl","name":"Curl de Bíceps alterno con Mancuernas","nameEn":"Dumbbell Curl","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Biceps","primaryMuscleEs":"Bíceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bicep_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bicep_Curl/1.jpg"]},{"id":"incline-dumbbell-curl","name":"Curl Inclinado con Mancuernas","nameEn":"Incline Dumbbell Curl","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Biceps","primaryMuscleEs":"Bíceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Curl/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('triceps-pushdown', 'Extensión de Tríceps en Polea Alta', 'Triceps Cable Pushdown', 'Hipertrofia', 'Triceps', 'Tríceps', '[]', 'Cable', 'Polea con Cable', 'Principiante', 'Aislamiento', 'Empuje Vertical', 'Empuje', '', '["Coloca una soga o barra recta en la polea en posición superior y sujétala.","Da un medio paso atrás inclinando un poco el torso hacia adelante, con los codos fijos a las costillas.","Extiende el codo por completo empujando la soga hacia el suelo, abriéndola en el fondo del movimiento.","Flexiona el codo dejando subir la soga hasta la altura del pecho superior de forma controlada."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Pushdown/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Pushdown/1.jpg"]', '[{"id":"skull-crusher","name":"Rompecráneos / Press Francés","nameEn":"Skull Crusher","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/EZ-Bar_Skullcrusher/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/EZ-Bar_Skullcrusher/1.jpg"]},{"id":"dumbbell-kickback","name":"Patada de Tríceps con Mancuerna","nameEn":"Dumbbell Triceps Kickback","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tricep_Dumbbell_Kickback/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tricep_Dumbbell_Kickback/1.jpg"]},{"id":"seated-triceps-dip-machine","name":"Fondos de Tríceps Sentado en Máquina","nameEn":"Seated Dip Machine for Triceps","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dip_Machine/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dip_Machine/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('overhead-cable-extension', 'Extensión de Tríceps sobre la Cabeza en Polea', 'Overhead Cable Triceps Extension', 'Hipertrofia', 'Triceps', 'Tríceps', '[]', 'Cable', 'Polea con Cable', 'Intermedio', 'Aislamiento', 'Empuje Vertical', 'Empuje', '', '["Dale la espalda a la polea y sujeta la soga llevándola detrás de tu cabeza.","Da un paso adelante e inclínate ligeramente.","Extiende los codos proyectando la soga hacia el frente.","Baja controlando el jalón detrás de tu cabeza."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Rope_Overhead_Triceps_Extension/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Rope_Overhead_Triceps_Extension/1.jpg"]', '[{"id":"skull-crusher","name":"Rompecráneos / Press Francés","nameEn":"Skull Crusher","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/EZ-Bar_Skullcrusher/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/EZ-Bar_Skullcrusher/1.jpg"]},{"id":"dumbbell-kickback","name":"Patada de Tríceps con Mancuerna","nameEn":"Dumbbell Triceps Kickback","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tricep_Dumbbell_Kickback/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tricep_Dumbbell_Kickback/1.jpg"]},{"id":"seated-triceps-dip-machine","name":"Fondos de Tríceps Sentado en Máquina","nameEn":"Seated Dip Machine for Triceps","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dip_Machine/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dip_Machine/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('skull-crusher', 'Rompecráneos / Press Francés', 'Skull Crusher', 'Hipertrofia', 'Triceps', 'Tríceps', '[]', 'Barbell', 'Barra Olímpica', 'Intermedio', 'Aislamiento', 'Empuje Vertical', 'Empuje', '', '["Acuéstate sobre un banco plano y sostén una barra EZ con los brazos estirados verticalmente sobre el rostro.","Lleva los brazos ligeramente en diagonal hacia atrás para mantener los tríceps trabajando bajo tensión constante.","Dobla únicamente el codo bajando la barra lentamente hacia tu frente o detrás de la cabeza.","Utiliza los tríceps para empujar la barra a la posición de partida."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/EZ-Bar_Skullcrusher/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/EZ-Bar_Skullcrusher/1.jpg"]', '[{"id":"triceps-pushdown","name":"Extensión de Tríceps en Polea Alta","nameEn":"Triceps Cable Pushdown","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Pushdown/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Pushdown/1.jpg"]},{"id":"overhead-cable-extension","name":"Extensión de Tríceps sobre la Cabeza en Polea","nameEn":"Overhead Cable Triceps Extension","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Rope_Overhead_Triceps_Extension/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Rope_Overhead_Triceps_Extension/1.jpg"]},{"id":"dumbbell-kickback","name":"Patada de Tríceps con Mancuerna","nameEn":"Dumbbell Triceps Kickback","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tricep_Dumbbell_Kickback/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tricep_Dumbbell_Kickback/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('close-grip-bench-press', 'Press de Banca Cerrado para Tríceps', 'Close Grip Bench Press', 'Hipertrofia', 'Triceps', 'Tríceps', '["Chest","Shoulders"]', 'Barbell', 'Barra Olímpica', 'Intermedio', 'Aislamiento', 'Empuje Horizontal', 'Empuje', '', '["Acuéstate en el banco y toma la barra con un agarre estrecho (al ancho de hombros).","Baja la barra lentamente hacia el pecho inferior con los codos pegados al cuerpo.","Empuja con fuerza de regreso usando los tríceps."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Barbell_Bench_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Barbell_Bench_Press/1.jpg"]', '[{"id":"skull-crushers-ez-bar","name":"Press Francés con Barra Z Acostado","nameEn":"Lying EZ-Bar Skull Crusher","equipment":"EZBar","equipmentEs":"Barra Z","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/EZ-Bar_Skullcrusher/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/EZ-Bar_Skullcrusher/1.jpg"]},{"id":"tate-press-dumbbells","name":"Press Tate con Mancuernas en Banco Plano","nameEn":"Flat Bench Dumbbell Tate Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tate_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tate_Press/1.jpg"]},{"id":"cable-kickback-triceps","name":"Patada de Tríceps Unilateral en Polea Baja","nameEn":"Single-Arm Cable Triceps Kickback","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_One_Arm_Tricep_Extension/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_One_Arm_Tricep_Extension/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('dumbbell-kickback', 'Patada de Tríceps con Mancuerna', 'Dumbbell Triceps Kickback', 'Hipertrofia', 'Triceps', 'Tríceps', '[]', 'Dumbbell', 'Mancuernas', 'Principiante', 'Aislamiento', 'Empuje Vertical', 'Empuje', '', '["Apoya una mano y rodilla en el banco, manteniendo la espalda recta.","Sostén la mancuerna levantando el codo hasta que el brazo quede paralelo al torso.","Extiende el codo hacia atrás por completo.","Baja la mancuerna a 90 grados de flexión controladamente."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tricep_Dumbbell_Kickback/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tricep_Dumbbell_Kickback/1.jpg"]', '[{"id":"triceps-pushdown","name":"Extensión de Tríceps en Polea Alta","nameEn":"Triceps Cable Pushdown","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Pushdown/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Pushdown/1.jpg"]},{"id":"overhead-cable-extension","name":"Extensión de Tríceps sobre la Cabeza en Polea","nameEn":"Overhead Cable Triceps Extension","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Rope_Overhead_Triceps_Extension/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Rope_Overhead_Triceps_Extension/1.jpg"]},{"id":"skull-crusher","name":"Rompecráneos / Press Francés","nameEn":"Skull Crusher","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/EZ-Bar_Skullcrusher/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/EZ-Bar_Skullcrusher/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('bench-dips', 'Fondos entre Bancos', 'Bench Dips', 'Calistenia', 'Triceps', 'Tríceps', '["Chest","Shoulders"]', 'Bodyweight', 'Peso Corporal', 'Principiante', 'Aislamiento', 'Empuje Vertical', 'Empuje', '', '["Coloca las manos en el borde de un banco detrás de ti y estira las piernas apoyadas en otro banco o suelo.","Baja el cuerpo doblando los codos hasta unos 90 grados.","Empuja con los tríceps para regresar arriba."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Dips/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Dips/1.jpg"]', '[{"id":"triceps-pushdown","name":"Extensión de Tríceps en Polea Alta","nameEn":"Triceps Cable Pushdown","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Pushdown/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Pushdown/1.jpg"]},{"id":"overhead-cable-extension","name":"Extensión de Tríceps sobre la Cabeza en Polea","nameEn":"Overhead Cable Triceps Extension","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Rope_Overhead_Triceps_Extension/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Rope_Overhead_Triceps_Extension/1.jpg"]},{"id":"skull-crusher","name":"Rompecráneos / Press Francés","nameEn":"Skull Crusher","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/EZ-Bar_Skullcrusher/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/EZ-Bar_Skullcrusher/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('barbell-squat', 'Sentadilla de Espalda con Barra', 'Barbell Back Squat', 'Hipertrofia', 'Quads', 'Cuádriceps', '["Glutes","Hamstrings","Abs"]', 'Barbell', 'Barra Olímpica', 'Intermedio', 'Compuesto', 'Sentadilla', 'Flexión/Extensión', '', '["Coloca la barra sobre el músculo trapecio superior de tu espalda alta (no en el cuello).","Desengancha del rack dando uno o dos pasos moderados hacia atrás.","Párate con pies al ancho de hombros con rodillas y puntas mirando levemente afuera.","Baja mandando cadera atrás y doblando rodillas de forma paralela en cuclillas.","Empuja con fuerza los talones y el centro de tus pies para subir de forma vertical y erguirte."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/1.jpg"]', '[{"id":"hack-squat","name":"Sentadilla Hack en Máquina","nameEn":"Hack Squat Machine","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hack_Squat/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hack_Squat/1.jpg"]},{"id":"leg-press","name":"Prensa de Pierna de 45 Grados","nameEn":"Leg Press","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Press/1.jpg"]},{"id":"leg-extension","name":"Extensiones de Cuádriceps en Máquina","nameEn":"Leg Extension","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Extensions/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Extensions/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('front-squat', 'Sentadilla Frontal con Barra', 'Barbell Front Squat', 'Fuerza', 'Quads', 'Cuádriceps', '["Glutes","Abs"]', 'Barbell', 'Barra Olímpica', 'Avanzado', 'Compuesto', 'Sentadilla', 'Flexión/Extensión', '', '["Coloca la barra sobre los hombros delanteros y crúzale los dedos para asegurar el agarre.","Mantén los codos en posición alta durante todo el movimiento.","Baja las caderas controlando la posición y cuidando no inclinar el torso.","Sube empujando activamente con los cuádriceps."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Barbell_Squat/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Barbell_Squat/1.jpg"]', '[{"id":"hack-squat","name":"Sentadilla Hack en Máquina","nameEn":"Hack Squat Machine","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hack_Squat/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hack_Squat/1.jpg"]},{"id":"leg-press","name":"Prensa de Pierna de 45 Grados","nameEn":"Leg Press","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Press/1.jpg"]},{"id":"leg-extension","name":"Extensiones de Cuádriceps en Máquina","nameEn":"Leg Extension","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Extensions/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Extensions/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('hack-squat', 'Sentadilla Hack en Máquina', 'Hack Squat Machine', 'Hipertrofia', 'Quads', 'Cuádriceps', '["Glutes","Hamstrings"]', 'Machine', 'Máquina de Palanca', 'Intermedio', 'Compuesto', 'Sentadilla', 'Flexión/Extensión', '', '["Apoya la espalda en el respaldo de la máquina Hack y coloca los hombros bajo las almohadillas.","Coloca los pies al ancho de hombros en la plataforma.","Baja de forma controlada flexionando las rodillas.","Empuja la plataforma hacia arriba extendiendo las piernas."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hack_Squat/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hack_Squat/1.jpg"]', '[{"id":"barbell-squat","name":"Sentadilla de Espalda con Barra","nameEn":"Barbell Back Squat","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/1.jpg"]},{"id":"zercher-squat-barbell","name":"Sentadilla Zercher con Barra en el Pliegue de los Codos","nameEn":"Zercher Squat with Barbell in Elbow Crook","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Zercher_Squats/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Zercher_Squats/1.jpg"]},{"id":"safety-bar-squat","name":"Sentadilla con Barra de Seguridad (SSB Squat)","nameEn":"Safety Squat Bar (SSB) Squat","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('leg-press', 'Prensa de Pierna de 45 Grados', 'Leg Press', 'Hipertrofia', 'Quads', 'Cuádriceps', '["Glutes","Hamstrings"]', 'Machine', 'Máquina de Palanca', 'Principiante', 'Compuesto', 'Sentadilla', 'Flexión/Extensión', '', '["Acomódate en el asiento de la prensa recargando la espalda lumbar contra el respaldo.","Coloca los pies en la plataforma en un patrón medio al ancho de caderas.","Quita los pestillos de seguridad y baja la plataforma doblando las rodillas hasta un ángulo aproximado de 90 grados.","Empuja con el talón y el tercio medio de la planta sin bloquear tus rodillas de golpe arriba."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Press/1.jpg"]', '[{"id":"barbell-squat","name":"Sentadilla de Espalda con Barra","nameEn":"Barbell Back Squat","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/1.jpg"]},{"id":"zercher-squat-barbell","name":"Sentadilla Zercher con Barra en el Pliegue de los Codos","nameEn":"Zercher Squat with Barbell in Elbow Crook","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Zercher_Squats/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Zercher_Squats/1.jpg"]},{"id":"safety-bar-squat","name":"Sentadilla con Barra de Seguridad (SSB Squat)","nameEn":"Safety Squat Bar (SSB) Squat","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('leg-extension', 'Extensiones de Cuádriceps en Máquina', 'Leg Extension', 'Hipertrofia', 'Quads', 'Cuádriceps', '[]', 'Machine', 'Máquina de Palanca', 'Principiante', 'Compuesto', 'Sentadilla', 'Flexión/Extensión', '', '["Siéntate ajustando la almohadilla del rodillo sobre tus tobillos.","Sostén los agarres laterales para evitar levantar el trasero.","Extiende las piernas por completo levantando el rodillo.","Baja lentamente resistiendo la carga."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Extensions/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Extensions/1.jpg"]', '[{"id":"barbell-squat","name":"Sentadilla de Espalda con Barra","nameEn":"Barbell Back Squat","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/1.jpg"]},{"id":"zercher-squat-barbell","name":"Sentadilla Zercher con Barra en el Pliegue de los Codos","nameEn":"Zercher Squat with Barbell in Elbow Crook","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Zercher_Squats/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Zercher_Squats/1.jpg"]},{"id":"safety-bar-squat","name":"Sentadilla con Barra de Seguridad (SSB Squat)","nameEn":"Safety Squat Bar (SSB) Squat","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('dumbbell-lunge', 'Zancadas con Mancuerna', 'Dumbbell Lunge', 'Hipertrofia', 'Quads', 'Cuádriceps', '["Glutes","Hamstrings"]', 'Dumbbell', 'Mancuernas', 'Principiante', 'Compuesto', 'Estocada', 'Flexión/Extensión', '', '["Sostén una mancuerna en cada mano erguido.","Da un paso amplio hacia adelante con una pierna.","Baja el cuerpo doblando ambas rodillas a 90 grados, con la rodilla trasera rozando el suelo.","Empuja con el talón delantero para volver al inicio."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Lunges/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Lunges/1.jpg"]', '[{"id":"walking-lunges-barbell","name":"Zancadas Caminando con Barra al Cuello","nameEn":"Barbell Walking Lunges","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Walking_Lunge/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Walking_Lunge/1.jpg"]},{"id":"alternating-reverse-lunge-reach","name":"Zancada Inversa Alterna con Extensión de Brazos","nameEn":"Reverse Lunge with Overhead Lateral Reach","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crossover_Reverse_Lunge/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crossover_Reverse_Lunge/1.jpg"]},{"id":"lateral-shuffle-cones","name":"Desplazamiento Lateral de Baloncesto (Shuffles)","nameEn":"Lateral Defensive Shuffle Drill","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_to_Side_Box_Shuffle/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_to_Side_Box_Shuffle/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('bulgarian-split-squat', 'Sentadilla Búlgara con Mancuerna', 'Bulgarian Split Squat', 'Hipertrofia', 'Quads', 'Cuádriceps', '["Glutes","Hamstrings"]', 'Dumbbell', 'Mancuernas', 'Intermedio', 'Compuesto', 'Estocada', 'Flexión/Extensión', '', '["Coloca un pie de apoyo atrás descansando el empeine del pie sobre un banco plano.","Da un paso moderado adelante con el otro pie sosteniendo una mancuerna en cada mano.","Desciende de forma vertical bajando la rodilla trasera hacia el suelo curvando levemente el torso si deseas enfatizar glúteo.","Empuja firmemente con el talón de la pierna delantera para regresar erguido."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Squat_with_Dumbbells/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Squat_with_Dumbbells/1.jpg"]', '[{"id":"walking-lunges-barbell","name":"Zancadas Caminando con Barra al Cuello","nameEn":"Barbell Walking Lunges","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Walking_Lunge/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Walking_Lunge/1.jpg"]},{"id":"alternating-reverse-lunge-reach","name":"Zancada Inversa Alterna con Extensión de Brazos","nameEn":"Reverse Lunge with Overhead Lateral Reach","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crossover_Reverse_Lunge/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crossover_Reverse_Lunge/1.jpg"]},{"id":"lateral-shuffle-cones","name":"Desplazamiento Lateral de Baloncesto (Shuffles)","nameEn":"Lateral Defensive Shuffle Drill","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_to_Side_Box_Shuffle/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_to_Side_Box_Shuffle/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('romanian-deadlift', 'Peso Muerto Rumano con Barra', 'Barbell Romanian Deadlift', 'Hipertrofia', 'Hamstrings', 'Isquiotibiales / Femoral', '["Glutes","Back"]', 'Barbell', 'Barra Olímpica', 'Intermedio', 'Compuesto', 'Bisagra de Cadera', 'Flexión/Extensión', '', '["Sostén la barra verticalmente estando de pie con los hombros relajados espalda recta.","Empieza a bajar la barra deslizando tus caderas directamente hacia atrás, como si quisieras empujar una puerta con los glúteos.","Mantén los hombros estables y la barra muy pegada a tus muslos doblando casi nada las rodillas.","Baja hasta que sientas el máximo estiramiento en los femorales traseros.","Haz fuerza con los glúteos para volver a enderezarte."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Romanian_Deadlift/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Romanian_Deadlift/1.jpg"]', '[{"id":"dumbbell-rdl","name":"Peso Muerto Rumano con Mancuernas","nameEn":"Dumbbell Romanian Deadlift","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Hamstrings","primaryMuscleEs":"Isquiotibiales / Femoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff-Legged_Dumbbell_Deadlift/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff-Legged_Dumbbell_Deadlift/1.jpg"]},{"id":"trap-bar-deadlift-low-handles","name":"Peso Muerto en Barra Hexagonal (Asas Bajas)","nameEn":"Trap Bar Deadlift Low Handles","equipment":"Trap Bar","equipmentEs":"Barra Hexagonal","primaryMuscle":"Hamstrings","primaryMuscleEs":"Isquiotibiales / Femoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Trap_Bar_Deadlift/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Trap_Bar_Deadlift/1.jpg"]},{"id":"lying-leg-curl","name":"Curl Femoral Acostado","nameEn":"Lying Leg Curl","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Hamstrings","primaryMuscleEs":"Isquiotibiales / Femoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Leg_Curls/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Leg_Curls/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('dumbbell-rdl', 'Peso Muerto Rumano con Mancuernas', 'Dumbbell Romanian Deadlift', 'Hipertrofia', 'Hamstrings', 'Isquiotibiales / Femoral', '["Glutes","Back"]', 'Dumbbell', 'Mancuernas', 'Principiante', 'Compuesto', 'Bisagra de Cadera', 'Flexión/Extensión', '', '["Sostén las mancuernas delante de tus piernas de pie.","Envía las caderas hacia atrás bajando las mancuernas pegadas a tus espinillas.","Contrae isquiotibiales y glúteos para regresar arriba."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff-Legged_Dumbbell_Deadlift/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff-Legged_Dumbbell_Deadlift/1.jpg"]', '[{"id":"romanian-deadlift","name":"Peso Muerto Rumano con Barra","nameEn":"Barbell Romanian Deadlift","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Hamstrings","primaryMuscleEs":"Isquiotibiales / Femoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Romanian_Deadlift/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Romanian_Deadlift/1.jpg"]},{"id":"trap-bar-deadlift-low-handles","name":"Peso Muerto en Barra Hexagonal (Asas Bajas)","nameEn":"Trap Bar Deadlift Low Handles","equipment":"Trap Bar","equipmentEs":"Barra Hexagonal","primaryMuscle":"Hamstrings","primaryMuscleEs":"Isquiotibiales / Femoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Trap_Bar_Deadlift/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Trap_Bar_Deadlift/1.jpg"]},{"id":"stiff-leg-deadlift-deficit","name":"Peso Muerto Piernas Semirrígidas con Déficit","nameEn":"Deficit Stiff-Legged Barbell Deadlift","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Hamstrings","primaryMuscleEs":"Isquiotibiales / Femoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff-Legged_Barbell_Deadlift/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff-Legged_Barbell_Deadlift/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('lying-leg-curl', 'Curl Femoral Acostado', 'Lying Leg Curl', 'Hipertrofia', 'Hamstrings', 'Isquiotibiales / Femoral', '[]', 'Machine', 'Máquina de Palanca', 'Principiante', 'Aislamiento', 'Bisagra de Cadera', 'Flexión/Extensión', '', '["Acuéstate boca abajo en la máquina de curl femoral.","Ubica el rodillo sobre los talones superiores.","Flexiona las rodillas jalando el peso hacia los glúteos.","Extiende controladamente las piernas."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Leg_Curls/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Leg_Curls/1.jpg"]', '[{"id":"romanian-deadlift","name":"Peso Muerto Rumano con Barra","nameEn":"Barbell Romanian Deadlift","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Hamstrings","primaryMuscleEs":"Isquiotibiales / Femoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Romanian_Deadlift/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Romanian_Deadlift/1.jpg"]},{"id":"dumbbell-rdl","name":"Peso Muerto Rumano con Mancuernas","nameEn":"Dumbbell Romanian Deadlift","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Hamstrings","primaryMuscleEs":"Isquiotibiales / Femoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff-Legged_Dumbbell_Deadlift/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff-Legged_Dumbbell_Deadlift/1.jpg"]},{"id":"trap-bar-deadlift-low-handles","name":"Peso Muerto en Barra Hexagonal (Asas Bajas)","nameEn":"Trap Bar Deadlift Low Handles","equipment":"Trap Bar","equipmentEs":"Barra Hexagonal","primaryMuscle":"Hamstrings","primaryMuscleEs":"Isquiotibiales / Femoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Trap_Bar_Deadlift/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Trap_Bar_Deadlift/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('seated-leg-curl', 'Curl Femoral Sentado', 'Seated Leg Curl', 'Hipertrofia', 'Hamstrings', 'Isquiotibiales / Femoral', '[]', 'Machine', 'Máquina de Palanca', 'Principiante', 'Aislamiento', 'Bisagra de Cadera', 'Flexión/Extensión', '', '["Siéntate y asegura el soporte de rodillas firmemente.","Coloca los talones sobre el rodillo de resistencia.","Flexiona las piernas empujando el rodillo hacia abajo.","Regresa despacio estirando por completo."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Leg_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Leg_Curl/1.jpg"]', '[{"id":"romanian-deadlift","name":"Peso Muerto Rumano con Barra","nameEn":"Barbell Romanian Deadlift","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Hamstrings","primaryMuscleEs":"Isquiotibiales / Femoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Romanian_Deadlift/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Romanian_Deadlift/1.jpg"]},{"id":"dumbbell-rdl","name":"Peso Muerto Rumano con Mancuernas","nameEn":"Dumbbell Romanian Deadlift","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Hamstrings","primaryMuscleEs":"Isquiotibiales / Femoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff-Legged_Dumbbell_Deadlift/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff-Legged_Dumbbell_Deadlift/1.jpg"]},{"id":"trap-bar-deadlift-low-handles","name":"Peso Muerto en Barra Hexagonal (Asas Bajas)","nameEn":"Trap Bar Deadlift Low Handles","equipment":"Trap Bar","equipmentEs":"Barra Hexagonal","primaryMuscle":"Hamstrings","primaryMuscleEs":"Isquiotibiales / Femoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Trap_Bar_Deadlift/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Trap_Bar_Deadlift/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('barbell-hip-thrust', 'Hip Thrust con Barra', 'Barbell Hip Thrust', 'Hipertrofia', 'Glutes', 'Glúteos', '["Hamstrings"]', 'Barbell', 'Barra Olímpica', 'Principiante', 'Compuesto', 'Bisagra de Cadera', 'Flexión/Extensión', '', '["Apoya tu espalda escapular alta firmemente contra el borde largo de un banco resistente.","Coloca la barra acolchada justo sobre el pliegue de tu pelvis.","Posiciona las rodillas de tal manera que a 90 grados apoyes firmemente la planta entera sobre el suelo.","Empuja la cadera hacia arriba apretando los glúteos de manera que queden alineados con rodillas e inserciones.","Baja controlando el peso a escasos centímetros del suelo."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hip_Thrust/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hip_Thrust/1.jpg"]', '[{"id":"dumbbell-glute-bridge","name":"Puente de Glúteos con Mancuerna","nameEn":"Dumbbell Glute Bridge","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Glutes","primaryMuscleEs":"Glúteos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Glute_Bridge/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Glute_Bridge/1.jpg"]},{"id":"cable-pull-through-glutes","name":"Pull-Through en Polea Baja con Cuerda para Glúteos","nameEn":"Low Cable Pull-Through for Glutes","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Glutes","primaryMuscleEs":"Glúteos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pull_Through/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pull_Through/1.jpg"]},{"id":"single-leg-hip-thrust-bench","name":"Hip Thrust a Una Pierna en Banco con Mancuerna","nameEn":"Single-Leg Dumbbell Hip Thrust","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Glutes","primaryMuscleEs":"Glúteos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single_Leg_Glute_Bridge/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single_Leg_Glute_Bridge/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('dumbbell-glute-bridge', 'Puente de Glúteos con Mancuerna', 'Dumbbell Glute Bridge', 'Hipertrofia', 'Glutes', 'Glúteos', '["Hamstrings"]', 'Dumbbell', 'Mancuernas', 'Principiante', 'Compuesto', 'Bisagra de Cadera', 'Flexión/Extensión', '', '["Acuéstate boca arriba con rodillas dobladas y pies apoyados en el suelo.","Coloca una mancuerna sobre tu pelvis.","Eleva la pelvis contrayendo los glúteos formando una línea recta desde los hombros a las rodillas.","Baja despacio."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Glute_Bridge/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Glute_Bridge/1.jpg"]', '[{"id":"barbell-hip-thrust","name":"Hip Thrust con Barra","nameEn":"Barbell Hip Thrust","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Glutes","primaryMuscleEs":"Glúteos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hip_Thrust/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hip_Thrust/1.jpg"]},{"id":"hip-thrust-barbell","name":"Hip Thrust con Barra (Empuje de Cadera)","nameEn":"Barbell Hip Thrust","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Glutes","primaryMuscleEs":"Glúteos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hip_Thrust/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hip_Thrust/1.jpg"]},{"id":"cable-pull-through-glutes","name":"Pull-Through en Polea Baja con Cuerda para Glúteos","nameEn":"Low Cable Pull-Through for Glutes","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Glutes","primaryMuscleEs":"Glúteos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pull_Through/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pull_Through/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('cable-kickback', 'Patada de Glúteo en Polea', 'Cable Glute Kickback', 'Hipertrofia', 'Glutes', 'Glúteos', '["Hamstrings"]', 'Cable', 'Polea con Cable', 'Intermedio', 'Aislamiento', 'Bisagra de Cadera', 'Flexión/Extensión', '', '["Coloca una tobillera a tu pie y conéctala a la polea baja.","Sostén el marco de la polea inclinado un poco adelante.","Patea el pie hacia atrás y hacia arriba contrayendo el glúteo.","Regresa despacio."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Glute_Kickback/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Glute_Kickback/1.jpg"]', '[{"id":"barbell-hip-thrust","name":"Hip Thrust con Barra","nameEn":"Barbell Hip Thrust","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Glutes","primaryMuscleEs":"Glúteos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hip_Thrust/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hip_Thrust/1.jpg"]},{"id":"dumbbell-glute-bridge","name":"Puente de Glúteos con Mancuerna","nameEn":"Dumbbell Glute Bridge","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Glutes","primaryMuscleEs":"Glúteos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Glute_Bridge/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Glute_Bridge/1.jpg"]},{"id":"hip-thrust-barbell","name":"Hip Thrust con Barra (Empuje de Cadera)","nameEn":"Barbell Hip Thrust","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Glutes","primaryMuscleEs":"Glúteos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hip_Thrust/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hip_Thrust/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('standing-calf-raise', 'Elevación de Gemelos de Pie con Barra', 'Standing Barbell Calf Raise', 'Hipertrofia', 'Calves', 'Gemelos / Pantorrillas', '[]', 'Barbell', 'Barra Olímpica', 'Principiante', 'Aislamiento', 'Sentadilla', 'Flexión/Extensión', '', '["Coloca la barra sobre la espalda alta.","Párate sobre el borde de un bloque metálico o disco.","Baja los talones por debajo del nivel del bloque para estirar.","Eleva los talones lo más alto posible apoyándote en las puntas de los pies."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Barbell_Calf_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Barbell_Calf_Raise/1.jpg"]', '[{"id":"seated-calf-raise","name":"Elevación de Gemelos Sentado","nameEn":"Seated Calf Raise","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Calves","primaryMuscleEs":"Gemelos / Pantorrillas","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Calf_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Calf_Raise/1.jpg"]},{"id":"seated-calf-raise-machine","name":"Elevación de Talones Sentado en Máquina (Sóleo)","nameEn":"Seated Calf Raise Machine","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Calves","primaryMuscleEs":"Gemelos / Pantorrillas","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Calf_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Calf_Raise/1.jpg"]},{"id":"donkey-calf-raise-machine","name":"Elevación de Gemelos Estilo Burro (Donkey Calf)","nameEn":"Donkey Calf Raise Machine","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Calves","primaryMuscleEs":"Gemelos / Pantorrillas","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Donkey_Calf_Raises/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Donkey_Calf_Raises/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('seated-calf-raise', 'Elevación de Gemelos Sentado', 'Seated Calf Raise', 'Hipertrofia', 'Calves', 'Gemelos / Pantorrillas', '[]', 'Machine', 'Máquina de Palanca', 'Principiante', 'Aislamiento', 'Sentadilla', 'Flexión/Extensión', '', '["Siéntate en la máquina apoyando la almohadilla sobre tus muslos bajos.","Coloca la punta de los pies en el bloque.","Eleva las puntas quitando el seguro, baja los talones al máximo y vuelve a elevar extendiendo al máximo el tobillo."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Calf_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Calf_Raise/1.jpg"]', '[{"id":"standing-calf-raise","name":"Elevación de Gemelos de Pie con Barra","nameEn":"Standing Barbell Calf Raise","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Calves","primaryMuscleEs":"Gemelos / Pantorrillas","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Barbell_Calf_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Barbell_Calf_Raise/1.jpg"]},{"id":"smith-machine-standing-calf-raise","name":"Elevación de Talones de Pie en Máquina Smith","nameEn":"Smith Machine Standing Calf Raise on Block","equipment":"SmithMachine","equipmentEs":"Máquina Smith / Multipower","primaryMuscle":"Calves","primaryMuscleEs":"Gemelos / Pantorrillas","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Calf_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Calf_Raise/1.jpg"]},{"id":"single-leg-isometric-calf-raise","name":"Sostenimiento Isométrico de Gemelo en Punta de Pie","nameEn":"Single-Leg Isometric Calf Raise Hold","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Calves","primaryMuscleEs":"Gemelos / Pantorrillas","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Donkey_Calf_Raises/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Donkey_Calf_Raises/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('ab-plank', 'Plancha Abdominal', 'Abdominal Plank', 'Isométrico', 'Abs', 'Abdomen / Core', '["Shoulders","Back"]', 'None', 'Sin Equipamiento', 'Principiante', 'Compuesto', 'Anti-Extensión', 'Core', '', '["Apoya tus antebrazos en el suelo alineando los codos justo bajo los hombros.","Estira tus piernas atrás apoyando las puntas de tus pies.","Contrae activamente el abdomen, los glúteos y las piernas creando fuerza en bloque.","Evita dejar caer la zona lumbar, mantén el cuello alineado neutro respirando rítmicamente."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plank/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plank/1.jpg"]', '[{"id":"hanging-leg-raise","name":"Elevación de Piernas Colgado","nameEn":"Hanging Leg Raise","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Abs","primaryMuscleEs":"Abdomen / Core","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hanging_Leg_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hanging_Leg_Raise/1.jpg"]},{"id":"russian-twist","name":"Giro Ruso con Disco/Mancuerna","nameEn":"Russian Twist","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Abs","primaryMuscleEs":"Abdomen / Core","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Russian_Twist/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Russian_Twist/1.jpg"]},{"id":"l-sit-floor","name":"L-Sit en el Suelo","nameEn":"Floor L-Sit","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Abs","primaryMuscleEs":"Abdomen / Core","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plank/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plank/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('ab-crunch', 'Crunch Abdominal', 'Abdominal Crunch', 'Isométrico', 'Abs', 'Abdomen / Core', '[]', 'None', 'Sin Equipamiento', 'Principiante', 'Compuesto', 'Anti-Extensión', 'Core', '', '["Acuéstate de espaldas con las rodillas flexionadas y pies en el suelo.","Coloca las manos ligeramente detrás de las orejas.","Eleva los hombros del suelo contrayendo el recto abdominal, sin tirar del cuello.","Baja con control."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crunches/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crunches/1.jpg"]', '[{"id":"hanging-leg-raise","name":"Elevación de Piernas Colgado","nameEn":"Hanging Leg Raise","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Abs","primaryMuscleEs":"Abdomen / Core","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hanging_Leg_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hanging_Leg_Raise/1.jpg"]},{"id":"russian-twist","name":"Giro Ruso con Disco/Mancuerna","nameEn":"Russian Twist","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Abs","primaryMuscleEs":"Abdomen / Core","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Russian_Twist/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Russian_Twist/1.jpg"]},{"id":"l-sit-floor","name":"L-Sit en el Suelo","nameEn":"Floor L-Sit","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Abs","primaryMuscleEs":"Abdomen / Core","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plank/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plank/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('hanging-leg-raise', 'Elevación de Piernas Colgado', 'Hanging Leg Raise', 'Isométrico', 'Abs', 'Abdomen / Core', '["Forearms"]', 'Bodyweight', 'Peso Corporal', 'Intermedio', 'Compuesto', 'Anti-Extensión', 'Core', '', '["Cuelga de la barra de tracción con los brazos totalmente extendidos.","Usa tu fuerza abdominal sin balancear el torso para elevar los pies o rodillas hacia el nivel de tu pecho.","Baja con total lentitud controlando la fuerza excéntrica."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hanging_Leg_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hanging_Leg_Raise/1.jpg"]', '[{"id":"ab-plank","name":"Plancha Abdominal","nameEn":"Abdominal Plank","equipment":"None","equipmentEs":"Sin Equipamiento","primaryMuscle":"Abs","primaryMuscleEs":"Abdomen / Core","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plank/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plank/1.jpg"]},{"id":"ab-crunch","name":"Crunch Abdominal","nameEn":"Abdominal Crunch","equipment":"None","equipmentEs":"Sin Equipamiento","primaryMuscle":"Abs","primaryMuscleEs":"Abdomen / Core","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crunches/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crunches/1.jpg"]},{"id":"russian-twist","name":"Giro Ruso con Disco/Mancuerna","nameEn":"Russian Twist","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Abs","primaryMuscleEs":"Abdomen / Core","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Russian_Twist/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Russian_Twist/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('russian-twist', 'Giro Ruso con Disco/Mancuerna', 'Russian Twist', 'Isométrico', 'Abs', 'Abdomen / Core', '[]', 'Dumbbell', 'Mancuernas', 'Principiante', 'Compuesto', 'Anti-Extensión', 'Core', '', '["Siéntate con rodillas dobladas, inclina el torso hacia atrás en 45 grados y despega los pies del suelo.","Sostén una mancuerna y gírala alternamente de lado a lado cruzando tu abdomen."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Russian_Twist/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Russian_Twist/1.jpg"]', '[{"id":"ab-plank","name":"Plancha Abdominal","nameEn":"Abdominal Plank","equipment":"None","equipmentEs":"Sin Equipamiento","primaryMuscle":"Abs","primaryMuscleEs":"Abdomen / Core","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plank/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plank/1.jpg"]},{"id":"ab-crunch","name":"Crunch Abdominal","nameEn":"Abdominal Crunch","equipment":"None","equipmentEs":"Sin Equipamiento","primaryMuscle":"Abs","primaryMuscleEs":"Abdomen / Core","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crunches/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crunches/1.jpg"]},{"id":"hanging-leg-raise","name":"Elevación de Piernas Colgado","nameEn":"Hanging Leg Raise","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Abs","primaryMuscleEs":"Abdomen / Core","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hanging_Leg_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hanging_Leg_Raise/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('ab-wheel-rollout', 'Rueda Abdominal', 'Ab Wheel Rollout', 'Fuerza', 'Abs', 'Abdomen / Core', '["Back","Shoulders"]', 'None', 'Sin Equipamiento', 'Avanzado', 'Compuesto', 'Anti-Extensión', 'Core', '', '["Arrodíllate en el suelo y sostén la rueda abdominal delante de ti.","Rueda la rueda hacia el frente estirando el cuerpo en una línea recta horizontal.","Contrae fuertemente el abdomen para regresar a la posición vertical."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ab_Roller/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ab_Roller/1.jpg"]', '[{"id":"hanging-leg-raise","name":"Elevación de Piernas Colgado","nameEn":"Hanging Leg Raise","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Abs","primaryMuscleEs":"Abdomen / Core","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hanging_Leg_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hanging_Leg_Raise/1.jpg"]},{"id":"russian-twist","name":"Giro Ruso con Disco/Mancuerna","nameEn":"Russian Twist","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Abs","primaryMuscleEs":"Abdomen / Core","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Russian_Twist/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Russian_Twist/1.jpg"]},{"id":"l-sit-floor","name":"L-Sit en el Suelo","nameEn":"Floor L-Sit","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Abs","primaryMuscleEs":"Abdomen / Core","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plank/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plank/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('wrist-curl', 'Curl de Muñeca con Barra', 'Wrist Curl', 'Hipertrofia', 'Forearms', 'Antebrazos', '[]', 'Barbell', 'Barra Olímpica', 'Principiante', 'Aislamiento', 'Tirón Horizontal', 'Tirón', '', '["Apoya los antebrazos sobre un banco con las manos colgando al borde sosteniendo la barra en supinación.","Flexiona la muñeca llevando la barra hacia arriba.","Baja la barra controlando la carga."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/1.jpg"]', '[{"id":"wrist-curls-dumbbell","name":"Curl de Muñeca Supino con Mancuerna para Antebrazo","nameEn":"Seated Dumbbell Wrist Curl","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Forearms","primaryMuscleEs":"Antebrazos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/1.jpg"]},{"id":"reverse-wrist-curl","name":"Curl de Muñeca Inverso","nameEn":"Reverse Wrist Curl","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Forearms","primaryMuscleEs":"Antebrazos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Down_Wrist_Curl_Over_A_Bench/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Down_Wrist_Curl_Over_A_Bench/1.jpg"]},{"id":"cross-body-hammer-curl","name":"Curl Martillo Cruzado al Pecho con Mancuerna","nameEn":"Cross-Body Dumbbell Hammer Curl","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Forearms","primaryMuscleEs":"Antebrazos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cross_Body_Hammer_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cross_Body_Hammer_Curl/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('reverse-wrist-curl', 'Curl de Muñeca Inverso', 'Reverse Wrist Curl', 'Hipertrofia', 'Forearms', 'Antebrazos', '[]', 'Barbell', 'Barra Olímpica', 'Principiante', 'Aislamiento', 'Tirón Horizontal', 'Tirón', '', '["Apoya los antebrazos con manos colgadas sosteniendo la barra en pronación (palmas boca abajo).","Extiende las muñecas subiendo la barra."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Down_Wrist_Curl_Over_A_Bench/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Down_Wrist_Curl_Over_A_Bench/1.jpg"]', '[{"id":"wrist-curls-dumbbell","name":"Curl de Muñeca Supino con Mancuerna para Antebrazo","nameEn":"Seated Dumbbell Wrist Curl","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Forearms","primaryMuscleEs":"Antebrazos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/1.jpg"]},{"id":"wrist-curl","name":"Curl de Muñeca con Barra","nameEn":"Wrist Curl","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Forearms","primaryMuscleEs":"Antebrazos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/1.jpg"]},{"id":"cross-body-hammer-curl","name":"Curl Martillo Cruzado al Pecho con Mancuerna","nameEn":"Cross-Body Dumbbell Hammer Curl","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Forearms","primaryMuscleEs":"Antebrazos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cross_Body_Hammer_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cross_Body_Hammer_Curl/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('treadmill-run', 'Carrera en Cinta', 'Treadmill Run', 'Cardio', 'Cardio', 'Sistema Cardiovascular', '["Quads","Calves"]', 'Machine', 'Máquina de Palanca', 'Principiante', 'Compuesto', 'Cardiovascular', 'Cardio', '', '["Configura la velocidad e inclinación en el monitor de control de la cinta.","Mantén tu postura erguida, la vista hacia el frente y un apoyo uniforme del pie.","Disfruta de una rutina constante de baja intensidad (LISS) o sprints rápidos progresivos."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jogging_Treadmill/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jogging_Treadmill/1.jpg"]', '[{"id":"jump-rope","name":"Salto de Cuerda","nameEn":"Jump Rope","equipment":"None","equipmentEs":"Sin Equipamiento","primaryMuscle":"Cardio","primaryMuscleEs":"Sistema Cardiovascular","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rope_Jumping/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rope_Jumping/1.jpg"]},{"id":"assault-bike-sprint","name":"Sprint Máximo en Bicicleta de Aire (Air Bike)","nameEn":"Air Bike All-Out Sprint","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Cardio","primaryMuscleEs":"Sistema Cardiovascular","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bicycling_Stationary/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bicycling_Stationary/1.jpg"]},{"id":"rowing-machine-500m","name":"Remoergómetro Prueba de 500 Metros","nameEn":"Concept2 Rowing Machine 500m Sprint","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Cardio","primaryMuscleEs":"Sistema Cardiovascular","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rowing_Stationary/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rowing_Stationary/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('stationary-bike', 'Bicicleta Estática', 'Stationary Bike', 'Cardio', 'Cardio', 'Sistema Cardiovascular', '["Quads","Hamstrings"]', 'Machine', 'Máquina de Palanca', 'Principiante', 'Compuesto', 'Cardiovascular', 'Cardio', '', '["Ajusta la altura del sillín al nivel de la cadera.","Pedalea manteniendo una cadencia constante y la columna neutral."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bicycling_Stationary/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bicycling_Stationary/1.jpg"]', '[{"id":"jump-rope","name":"Salto de Cuerda","nameEn":"Jump Rope","equipment":"None","equipmentEs":"Sin Equipamiento","primaryMuscle":"Cardio","primaryMuscleEs":"Sistema Cardiovascular","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rope_Jumping/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rope_Jumping/1.jpg"]},{"id":"assault-bike-sprint","name":"Sprint Máximo en Bicicleta de Aire (Air Bike)","nameEn":"Air Bike All-Out Sprint","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Cardio","primaryMuscleEs":"Sistema Cardiovascular","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bicycling_Stationary/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bicycling_Stationary/1.jpg"]},{"id":"rowing-machine-500m","name":"Remoergómetro Prueba de 500 Metros","nameEn":"Concept2 Rowing Machine 500m Sprint","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Cardio","primaryMuscleEs":"Sistema Cardiovascular","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rowing_Stationary/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rowing_Stationary/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLU