INSERT INTO exercises VALUES ('rowing-machine', 'Máquina de Remo (Ergómetro)', 'Rowing Machine', 'Cardio', 'Cardio', 'Sistema Cardiovascular', '["Back","Legs","Arms"]', 'Machine', 'Máquina de Palanca', 'Intermedio', 'Compuesto', 'Cardiovascular', 'Cardio', '', '["Siéntate con los pies asegurados en los estribos.","Empuja con las piernas, inclina el torso atrás y jala el manillar hacia el pecho bajo.","Regresa las manos, el torso y flexiona las piernas."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rowing_Stationary/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rowing_Stationary/1.jpg"]', '[{"id":"jump-rope","name":"Salto de Cuerda","nameEn":"Jump Rope","equipment":"None","equipmentEs":"Sin Equipamiento","primaryMuscle":"Cardio","primaryMuscleEs":"Sistema Cardiovascular","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rope_Jumping/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rope_Jumping/1.jpg"]},{"id":"assault-bike-sprint","name":"Sprint Máximo en Bicicleta de Aire (Air Bike)","nameEn":"Air Bike All-Out Sprint","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Cardio","primaryMuscleEs":"Sistema Cardiovascular","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bicycling_Stationary/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bicycling_Stationary/1.jpg"]},{"id":"rowing-machine-500m","name":"Remoergómetro Prueba de 500 Metros","nameEn":"Concept2 Rowing Machine 500m Sprint","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Cardio","primaryMuscleEs":"Sistema Cardiovascular","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rowing_Stationary/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rowing_Stationary/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('elliptical-trainer', 'Elíptica', 'Elliptical Trainer', 'Cardio', 'Cardio', 'Sistema Cardiovascular', '["Quads","Glutes"]', 'Machine', 'Máquina de Palanca', 'Principiante', 'Compuesto', 'Cardiovascular', 'Cardio', '', '["Súbete a los pedales y toma los agarres móviles.","Muévete en un movimiento fluido de zancada elíptica empujando con brazos y piernas."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Elliptical_Trainer/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Elliptical_Trainer/1.jpg"]', '[{"id":"jump-rope","name":"Salto de Cuerda","nameEn":"Jump Rope","equipment":"None","equipmentEs":"Sin Equipamiento","primaryMuscle":"Cardio","primaryMuscleEs":"Sistema Cardiovascular","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rope_Jumping/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rope_Jumping/1.jpg"]},{"id":"assault-bike-sprint","name":"Sprint Máximo en Bicicleta de Aire (Air Bike)","nameEn":"Air Bike All-Out Sprint","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Cardio","primaryMuscleEs":"Sistema Cardiovascular","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bicycling_Stationary/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bicycling_Stationary/1.jpg"]},{"id":"rowing-machine-500m","name":"Remoergómetro Prueba de 500 Metros","nameEn":"Concept2 Rowing Machine 500m Sprint","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Cardio","primaryMuscleEs":"Sistema Cardiovascular","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rowing_Stationary/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rowing_Stationary/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('jump-rope', 'Salto de Cuerda', 'Jump Rope', 'Cardio', 'Cardio', 'Sistema Cardiovascular', '["Calves","Shoulders"]', 'None', 'Sin Equipamiento', 'Principiante', 'Compuesto', 'Cardiovascular', 'Cardio', '', '["Sostén los mangos a los lados de tus caderas.","Salta en las puntas de los pies mientras rotas la cuerda con las muñecas."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rope_Jumping/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rope_Jumping/1.jpg"]', '[{"id":"treadmill-run","name":"Carrera en Cinta","nameEn":"Treadmill Run","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Cardio","primaryMuscleEs":"Sistema Cardiovascular","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jogging_Treadmill/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jogging_Treadmill/1.jpg"]},{"id":"stationary-bike","name":"Bicicleta Estática","nameEn":"Stationary Bike","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Cardio","primaryMuscleEs":"Sistema Cardiovascular","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bicycling_Stationary/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bicycling_Stationary/1.jpg"]},{"id":"rowing-machine","name":"Máquina de Remo (Ergómetro)","nameEn":"Rowing Machine","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Cardio","primaryMuscleEs":"Sistema Cardiovascular","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rowing_Stationary/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rowing_Stationary/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('incline-dumbbell-flyes', 'Aperturas Inclinadas con Mancuernas', 'Incline Dumbbell Flyes', 'Hipertrofia', 'Chest', 'Pecho / Pectoral', '["Shoulders"]', 'Dumbbell', 'Mancuernas', 'Intermedio', 'Aislamiento', 'Empuje Horizontal', 'Empuje', '', '["Ajusta un banco inclinado entre 30 y 45 grados y siéntate apoyando la espalda por completo.","Sujeta dos mancuernas con agarre neutro y elévalas sobre el pecho con los codos ligeramente flexionados.","Abre los brazos en un arco amplio descendiendo las mancuernas hasta sentir un estiramiento profundo en el pectoral superior.","Cierra los brazos contrayendo el pecho por la misma trayectoria hasta la posición inicial sin chocar las mancuernas."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Flyes/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Flyes/1.jpg"]', '[{"id":"pec-deck-fly","name":"Aperturas en Contratora (Pec Deck)","nameEn":"Pec Deck Fly","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butterfly/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butterfly/1.jpg"]},{"id":"seated-cable-flyes","name":"Cruces en Polea Sentado en Banco","nameEn":"Seated Cable Flyes","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flat_Bench_Cable_Flyes/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flat_Bench_Cable_Flyes/1.jpg"]},{"id":"barbell-bench-press","name":"Press de Banca con Barra","nameEn":"Barbell Bench Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('svend-press', 'Press Svend con Discos', 'Svend Press', 'Isométrico', 'Chest', 'Pecho / Pectoral', '["Shoulders"]', 'Dumbbell', 'Mancuernas', 'Principiante', 'Aislamiento', 'Empuje Horizontal', 'Empuje', '', '["Ponte de pie con los pies a la anchura de las caderas y la espalda erguida.","Coloca uno o dos discos pequeños (o una mancuerna) entre las palmas de las manos a la altura del esternón.","Presiona activamente las palmas entre sí con fuerza isométrica máxima apretando el pecho.","Empuja las manos hacia adelante hasta estirar los brazos por completo sin aflojar la presión entre las palmas.","Regresa controladamente al esternón manteniendo la compresión continua."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Isometric_Chest_Squeezes/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Isometric_Chest_Squeezes/1.jpg"]', '[{"id":"pec-deck-fly","name":"Aperturas en Contratora (Pec Deck)","nameEn":"Pec Deck Fly","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butterfly/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butterfly/1.jpg"]},{"id":"seated-cable-flyes","name":"Cruces en Polea Sentado en Banco","nameEn":"Seated Cable Flyes","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flat_Bench_Cable_Flyes/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flat_Bench_Cable_Flyes/1.jpg"]},{"id":"barbell-bench-press","name":"Press de Banca con Barra","nameEn":"Barbell Bench Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('seated-cable-flyes', 'Cruces en Polea Sentado en Banco', 'Seated Cable Flyes', 'Hipertrofia', 'Chest', 'Pecho / Pectoral', '["Shoulders"]', 'Cable', 'Polea con Cable', 'Principiante', 'Aislamiento', 'Empuje Horizontal', 'Empuje', '', '["Coloca un banco con respaldo a 90 grados en medio de una estación de poleas dobles ajustadas a la altura del pecho.","Siéntate apoyando firmemente la espalda y toma los agarres individuales.","Junta las manos hacia el frente en un arco amplio con los codos ligeramente doblados.","Aguanta un segundo la contracción máxima en el centro y abre los brazos despacio sintiendo la tensión continua del cable."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flat_Bench_Cable_Flyes/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flat_Bench_Cable_Flyes/1.jpg"]', '[{"id":"dumbbell-fly","name":"Aperturas con Mancuernas","nameEn":"Dumbbell Fly","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Flyes/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Flyes/1.jpg"]},{"id":"incline-dumbbell-fly","name":"Aperturas Inclinadas con Mancuernas","nameEn":"Incline Dumbbell Fly","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Flyes/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Flyes/1.jpg"]},{"id":"pec-deck-fly","name":"Aperturas en Contratora (Pec Deck)","nameEn":"Pec Deck Fly","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butterfly/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butterfly/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('single-arm-cable-chest-press', 'Press de Pecho en Polea a Una Mano', 'Single-Arm Cable Chest Press', 'Funcional', 'Chest', 'Pecho / Pectoral', '["Triceps","Shoulders"]', 'Cable', 'Polea con Cable', 'Intermedio', 'Compuesto', 'Empuje Horizontal', 'Empuje', '', '["Ajusta la polea a la altura del pecho y toma el agarre con una mano situándote de espaldas a la torre en posición de zancada firme.","Comienza con la mano al lado del pecho y el core completamente rígido para resistir la rotación.","Empuja el agarre hacia el frente en línea recta hasta extender el brazo.","Regresa lentamente sin permitir que el peso rote tu tronco hacia atrás."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Chest_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Chest_Press/1.jpg"]', '[{"id":"trx-chest-press","name":"Press de Pecho en Suspensión (TRX Chest Press)","nameEn":"TRX Suspension Chest Press","equipment":"TRX","equipmentEs":"TRX / Suspensión","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Push-Up/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Push-Up/1.jpg"]},{"id":"trx-chest-flye","name":"Aperturas de Pecho en Suspensión (TRX Flye)","nameEn":"TRX Suspension Chest Flye","equipment":"TRX","equipmentEs":"TRX / Suspensión","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Push-Up/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Push-Up/1.jpg"]},{"id":"trx-atomic-push-up","name":"Flexión Atómica con Pies en TRX (Push-Up + Crunch)","nameEn":"TRX Atomic Push-Up to Pike","equipment":"TRX","equipmentEs":"TRX / Suspensión","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Push-Up/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Push-Up/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('chest-supported-t-bar-row', 'Remo en Barra T con Apoyo al Pecho', 'Chest-Supported T-Bar Row', 'Hipertrofia', 'Back', 'Espalda / Dorsal', '["Biceps","Traps","Forearms"]', 'Machine', 'Máquina de Palanca', 'Principiante', 'Compuesto', 'Tirón Horizontal', 'Tirón', '', '["Apoya el pecho firmemente contra la almohadilla inclinada de la máquina y asegura los pies en las plataformas.","Toma los agarres con las manos en pronación o agarre neutro con brazos totalmente estirados.","Tira de las empuñaduras llevando los codos hacia atrás y apretando las escápulas con fuerza en el punto alto.","Baja el peso con una cadencia controlada de 2 a 3 segundos hasta sentir el estiramiento escapular completo."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_T-Bar_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_T-Bar_Row/1.jpg"]', '[{"id":"barbell-row","name":"Remo con Barra","nameEn":"Barbell Row","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/1.jpg"]},{"id":"dumbbell-single-row","name":"Remo a una Mano con Mancuerna","nameEn":"Dumbbell Single-Arm Row","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/1.jpg"]},{"id":"seated-cable-row","name":"Remo Sentado en Polea con Agarre Gironda","nameEn":"Seated Cable Row","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Cable_Rows/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Cable_Rows/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('single-arm-dumbbell-row', 'Remo con Mancuerna a Una Mano Apoyado en Banco', 'Single-Arm Dumbbell Row', 'Hipertrofia', 'Back', 'Espalda / Dorsal', '["Lats","Biceps","Forearms"]', 'Dumbbell', 'Mancuernas', 'Principiante', 'Compuesto', 'Tirón Horizontal', 'Tirón', '', '["Coloca la rodilla y la mano derecha apoyadas firmemente sobre un banco plano, con la espalda paralela al suelo.","Toma una mancuerna con la mano izquierda con el brazo colgando hacia el suelo en extensión relajada.","Tira de la mancuerna guiando el codo hacia el bolsillo trasero de la cadera, sin girar el tronco.","Aprieta el dorsal arriba un instante y baja con lentitud extendiendo por completo el brazo."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/1.jpg"]', '[{"id":"barbell-row","name":"Remo con Barra","nameEn":"Barbell Row","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/1.jpg"]},{"id":"t-bar-row","name":"Remo en Barra T","nameEn":"T-Bar Row","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/1.jpg"]},{"id":"seated-cable-row","name":"Remo Sentado en Polea con Agarre Gironda","nameEn":"Seated Cable Row","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Cable_Rows/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Cable_Rows/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('inverted-row', 'Remo Invertido (Remo Australiano)', 'Inverted Row (Australian Pull-Up)', 'Calistenia', 'Back', 'Espalda / Dorsal', '["Biceps","Traps","Forearms"]', 'Bodyweight', 'Peso Corporal', 'Principiante', 'Compuesto', 'Tirón Horizontal', 'Tirón', '', '["Coloca una barra fija en un rack a la altura de la cadera y túmbate debajo mirando hacia arriba.","Sujeta la barra con agarre prono un poco más ancho que los hombros y apoya los talones en el suelo con el cuerpo recto.","Tira del pecho hacia la barra contrayendo la espalda alta hasta que el esternón toque o quede a centímetros de la barra.","Baja el cuerpo con control hasta estirar los brazos completamente sin romper la línea recta corporal."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Inverted_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Inverted_Row/1.jpg"]', '[{"id":"barbell-row","name":"Remo con Barra","nameEn":"Barbell Row","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/1.jpg"]},{"id":"t-bar-row","name":"Remo en Barra T","nameEn":"T-Bar Row","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/1.jpg"]},{"id":"dumbbell-single-row","name":"Remo a una Mano con Mancuerna","nameEn":"Dumbbell Single-Arm Row","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Back","primaryMuscleEs":"Espalda / Dorsal","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('straight-arm-cable-pulldown', 'Pull-Over en Polea Alta con Brazos Rectos', 'Straight-Arm Cable Pulldown', 'Hipertrofia', 'Lats', 'Dorsal Ancho', '["Triceps","Chest"]', 'Cable', 'Polea con Cable', 'Principiante', 'Aislamiento', 'Tirón Vertical', 'Tirón', '', '["Coloca una barra recta o cuerda en la polea alta y tómala con las palmas hacia abajo.","Da un paso hacia atrás, inclina el tronco unos 30 grados con caderas flexionadas y mantén los brazos semirrectos.","Tracciona la barra en un arco descendente hacia los muslos exclusivamente contrayendo los dorsales.","Aprieta los dorsales abajo durante un segundo y regresa despacio hasta sentir el estiramiento completo arriba."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Straight-Arm_Pulldown/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Straight-Arm_Pulldown/1.jpg"]', '[{"id":"neutral-grip-pullup","name":"Dominadas con Agarre Neutro","nameEn":"Neutral Grip Pull-Up","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Lats","primaryMuscleEs":"Dorsal Ancho","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pullups/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pullups/1.jpg"]},{"id":"wide-grip-pullup","name":"Dominadas Pronas con Agarre Ancho","nameEn":"Wide Grip Pull-Up","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Lats","primaryMuscleEs":"Dorsal Ancho","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Rear_Pull-Up/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Rear_Pull-Up/1.jpg"]},{"id":"archer-pullup","name":"Dominadas de Arquero","nameEn":"Archer Pull-Up","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Lats","primaryMuscleEs":"Dorsal Ancho","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Mixed_Grip_Chin/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Mixed_Grip_Chin/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('face-pull-rope', 'Face Pull con Cuerda en Polea', 'Rope Cable Face Pull', 'Rehabilitación', 'Shoulders', 'Hombros / Deltoides', '["Traps","Back"]', 'Cable', 'Polea con Cable', 'Principiante', 'Compuesto', 'Tirón Horizontal', 'Tirón', '', '["Ajusta la polea a la altura de los ojos y toma la cuerda con agarre neutro (pulgares hacia atrás).","Da un paso atrás con rodillas semiflexionadas y el tronco estable.","Tira de la cuerda hacia la cara separando las manos y llevando los codos altos y hacia atrás.","Al final del movimiento, rota externamente los hombros mostrando los nudillos hacia atrás.","Regresa con lentitud a la posición de brazos extendidos."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Face_Pull/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Face_Pull/1.jpg"]', '[{"id":"prone-w-raise-bench","name":"Elevaciones en W Boca Abajo para Manguito Rotador","nameEn":"Prone Incline Bench W-Raise","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Incline_Shoulder_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Incline_Shoulder_Raise/1.jpg"]},{"id":"band-pull-apart-warmup","name":"Separaciones de Banda Elástica al Pecho (Pull-Apart)","nameEn":"Band Pull-Apart Warmup","equipment":"Band","equipmentEs":"Banda Elástica","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Pull_Apart/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Pull_Apart/1.jpg"]},{"id":"face-pull-band-warmup","name":"Face Pull con Banda Elástica en Anclaje","nameEn":"Banded Face Pull Warmup","equipment":"Band","equipmentEs":"Banda Elástica","primaryMuscle":"Shoulders","primaryMuscleEs":"Hombros / Deltoides","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Pull_Apart/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Pull_Apart/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('spider-curl', 'Curl Araña con Barra Z en Banco Inclinado', 'Spider Curl with EZ Bar', 'Hipertrofia', 'Biceps', 'Bíceps', '["Forearms"]', 'EZBar', 'Barra Z', 'Intermedio', 'Aislamiento', 'Tirón Vertical', 'Flexión/Extensión', '', '["Apoya el pecho sobre la parte superior de un banco inclinado a 45 grados mirando hacia el suelo.","Sujeta la barra Z con agarre supino dejando que los brazos cuelguen rectos verticalmente.","Flexiona los codos elevando la barra hacia la frente con aislamiento absoluto sin balanceo.","Pausa un segundo en la contracción pico y desciende lentamente hasta la vertical."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Spider_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Spider_Curl/1.jpg"]', '[{"id":"barbell-curl","name":"Curl de Bíceps con Barra EZ","nameEn":"Barbell Curl","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Biceps","primaryMuscleEs":"Bíceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curl/1.jpg"]},{"id":"dumbbell-curl","name":"Curl de Bíceps alterno con Mancuernas","nameEn":"Dumbbell Curl","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Biceps","primaryMuscleEs":"Bíceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bicep_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bicep_Curl/1.jpg"]},{"id":"incline-dumbbell-curl","name":"Curl Inclinado con Mancuernas","nameEn":"Incline Dumbbell Curl","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Biceps","primaryMuscleEs":"Bíceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Curl/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('overhead-cable-triceps-extension', 'Extensión de Tríceps sobre la Cabeza en Polea', 'Overhead Cable Triceps Extension', 'Hipertrofia', 'Triceps', 'Tríceps', '["Forearms"]', 'Cable', 'Polea con Cable', 'Principiante', 'Aislamiento', 'Empuje Vertical', 'Flexión/Extensión', '', '["Coloca una cuerda en una polea a media altura o baja y colócate de espaldas a la torre.","Lleva la cuerda por detrás de tu nuca con codos flexionados apuntando hacia adelante.","Da un paso adelante en zancada para dar estabilidad al tronco inclinado unos 30 grados.","Extiende los brazos hacia adelante y arriba bloqueando los tríceps con apertura de cuerda al final.","Flexiona los codos hacia atrás sintiendo un gran estiramiento en la cabeza larga del tríceps."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Rope_Overhead_Triceps_Extension/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Rope_Overhead_Triceps_Extension/1.jpg"]', '[{"id":"skull-crusher","name":"Rompecráneos / Press Francés","nameEn":"Skull Crusher","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/EZ-Bar_Skullcrusher/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/EZ-Bar_Skullcrusher/1.jpg"]},{"id":"dumbbell-kickback","name":"Patada de Tríceps con Mancuerna","nameEn":"Dumbbell Triceps Kickback","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tricep_Dumbbell_Kickback/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tricep_Dumbbell_Kickback/1.jpg"]},{"id":"seated-triceps-dip-machine","name":"Fondos de Tríceps Sentado en Máquina","nameEn":"Seated Dip Machine for Triceps","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dip_Machine/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dip_Machine/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('skull-crushers-ez-bar', 'Press Francés con Barra Z Acostado', 'Lying EZ-Bar Skull Crusher', 'Hipertrofia', 'Triceps', 'Tríceps', '["Forearms"]', 'EZBar', 'Barra Z', 'Intermedio', 'Aislamiento', 'Empuje Horizontal', 'Flexión/Extensión', '', '["Acuéstate sobre un banco plano sosteniendo una barra Z con agarre estrecho sobre el pecho.","Lleva los brazos ligeramente inclinados hacia atrás (hacia la cabeza) unos 10-15 grados para mantener tensión.","Flexiona únicamente los codos bajando la barra hacia la coronilla de la cabeza de forma controlada.","Extiende los antebrazos con fuerza de los tríceps regresando a la posición inicial sin mover los brazos superiores."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/EZ-Bar_Skullcrusher/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/EZ-Bar_Skullcrusher/1.jpg"]', '[{"id":"close-grip-bench-press","name":"Press de Banca Cerrado para Tríceps","nameEn":"Close Grip Bench Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Barbell_Bench_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Barbell_Bench_Press/1.jpg"]},{"id":"tate-press-dumbbells","name":"Press Tate con Mancuernas en Banco Plano","nameEn":"Flat Bench Dumbbell Tate Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tate_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tate_Press/1.jpg"]},{"id":"california-press-barbell","name":"Press California (Híbrido Cerrado + Press Francés)","nameEn":"Barbell California Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Barbell_Bench_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Barbell_Bench_Press/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('hack-squat-machine', 'Sentadilla Hack en Máquina', 'Hack Squat Machine', 'Hipertrofia', 'Quads', 'Cuádriceps', '["Glutes","Hamstrings"]', 'Machine', 'Máquina de Palanca', 'Intermedio', 'Compuesto', 'Sentadilla', 'Empuje', '', '["Apoya la espalda y hombros firmemente contra las almohadillas de la máquina Hack y coloca los pies en el centro de la plataforma.","Desengancha los seguros laterales y desciende flexionando las rodillas de forma controlada.","Baja profundamente hasta formar al menos un ángulo de 90 grados o hasta que los muslos toquen las pantorrillas.","Empuja la plataforma con toda la planta de los pies extendiendo las rodillas sin bloquearlas de golpe arriba."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hack_Squat/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hack_Squat/1.jpg"]', '[{"id":"barbell-squat","name":"Sentadilla de Espalda con Barra","nameEn":"Barbell Back Squat","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/1.jpg"]},{"id":"zercher-squat-barbell","name":"Sentadilla Zercher con Barra en el Pliegue de los Codos","nameEn":"Zercher Squat with Barbell in Elbow Crook","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Zercher_Squats/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Zercher_Squats/1.jpg"]},{"id":"safety-bar-squat","name":"Sentadilla con Barra de Seguridad (SSB Squat)","nameEn":"Safety Squat Bar (SSB) Squat","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('leg-press-45', 'Prensa de Piernas a 45 Grados', '45-Degree Leg Press', 'Hipertrofia', 'Quads', 'Cuádriceps', '["Glutes","Hamstrings"]', 'Machine', 'Máquina de Palanca', 'Principiante', 'Compuesto', 'Sentadilla', 'Empuje', '', '["Siéntate en la máquina apoyando la zona lumbar firmemente contra el respaldo sin despegar los glúteos del asiento.","Coloca los pies en la plataforma a la anchura de los hombros y quita los topes de seguridad con las palancas laterales.","Flexiona las piernas bajando la plataforma de manera fluida hasta que las rodillas queden cerca del pecho a 90 grados.","Empuja con los talones y parte media del pie regresando la plataforma sin extender bruscamente las rodillas al final."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Press/1.jpg"]', '[{"id":"barbell-squat","name":"Sentadilla de Espalda con Barra","nameEn":"Barbell Back Squat","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/1.jpg"]},{"id":"zercher-squat-barbell","name":"Sentadilla Zercher con Barra en el Pliegue de los Codos","nameEn":"Zercher Squat with Barbell in Elbow Crook","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Zercher_Squats/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Zercher_Squats/1.jpg"]},{"id":"safety-bar-squat","name":"Sentadilla con Barra de Seguridad (SSB Squat)","nameEn":"Safety Squat Bar (SSB) Squat","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('hip-thrust-barbell', 'Hip Thrust con Barra (Empuje de Cadera)', 'Barbell Hip Thrust', 'Hipertrofia', 'Glutes', 'Glúteos', '["Hamstrings","Quads"]', 'Barbell', 'Barra Olímpica', 'Intermedio', 'Compuesto', 'Bisagra de Cadera', 'Empuje', '', '["Siéntate en el suelo con la espalda alta (borde inferior de las escápulas) apoyada contra un banco acolchado firme.","Haz rodar una barra cargada con protector sobre tus muslos hasta ubicarla sobre el pliegue de las caderas.","Coloca los pies firmes en el suelo de modo que, al elevar la cadera, las espinillas queden totalmente verticales a 90 grados.","Empuja a través de los talones extendiendo las caderas hacia arriba hasta alinear torso y muslos paralelos al suelo.","Aprieta los glúteos en la cima un segundo con retroversión pélvica y desciende controladamente sin arquear el cuello."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hip_Thrust/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hip_Thrust/1.jpg"]', '[{"id":"dumbbell-glute-bridge","name":"Puente de Glúteos con Mancuerna","nameEn":"Dumbbell Glute Bridge","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Glutes","primaryMuscleEs":"Glúteos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Glute_Bridge/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Glute_Bridge/1.jpg"]},{"id":"cable-pull-through-glutes","name":"Pull-Through en Polea Baja con Cuerda para Glúteos","nameEn":"Low Cable Pull-Through for Glutes","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Glutes","primaryMuscleEs":"Glúteos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pull_Through/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pull_Through/1.jpg"]},{"id":"single-leg-hip-thrust-bench","name":"Hip Thrust a Una Pierna en Banco con Mancuerna","nameEn":"Single-Leg Dumbbell Hip Thrust","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Glutes","primaryMuscleEs":"Glúteos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single_Leg_Glute_Bridge/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single_Leg_Glute_Bridge/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('glute-bridge-barbell', 'Puente de Glúteos con Barra en el Suelo', 'Barbell Glute Bridge', 'Fuerza', 'Glutes', 'Glúteos', '["Hamstrings"]', 'Barbell', 'Barra Olímpica', 'Principiante', 'Compuesto', 'Bisagra de Cadera', 'Empuje', '', '["Acuéstate boca arriba en el suelo con las rodillas dobladas y los pies planos al suelo a la anchura de las caderas.","Coloca la barra protegida sobre las caderas sosteniéndola con ambas manos para evitar que ruede.","Eleva las caderas despegando los glúteos del piso hasta que los muslos queden en línea con el torso.","Contrae intensamente los glúteos en el punto alto y baja la cadera rozando apenas el suelo antes de repetir."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Glute_Bridge/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Glute_Bridge/1.jpg"]', '[{"id":"dumbbell-glute-bridge","name":"Puente de Glúteos con Mancuerna","nameEn":"Dumbbell Glute Bridge","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Glutes","primaryMuscleEs":"Glúteos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Glute_Bridge/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Glute_Bridge/1.jpg"]},{"id":"single-leg-glute-bridge","name":"Puente de Glúteos a Una Pierna","nameEn":"Single-Leg Glute Bridge","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Glutes","primaryMuscleEs":"Glúteos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single_Leg_Glute_Bridge/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single_Leg_Glute_Bridge/1.jpg"]},{"id":"glute-bridge-activation-bodyweight","name":"Puente de Glúteos de Activación con Doble Apoyo","nameEn":"Bodyweight Glute Bridge Holds","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Glutes","primaryMuscleEs":"Glúteos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butt_Lift_Bridge/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butt_Lift_Bridge/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('seated-leg-curl-machine', 'Curl Femoral Sentado en Máquina', 'Seated Leg Curl Machine', 'Hipertrofia', 'Hamstrings', 'Isquiotibiales / Femoral', '["Calves"]', 'Machine', 'Máquina de Palanca', 'Principiante', 'Aislamiento', 'Bisagra de Cadera', 'Flexión/Extensión', '', '["Ajusta el respaldo para que el eje de rotación de la máquina coincida con tus rodillas y asegura la almohadilla superior sobre tus muslos.","Coloca la parte posterior de los tobillos sobre el rodillo inferior acolchado.","Flexiona las piernas hacia abajo y atrás contrayendo los isquiotibiales hasta el tope de recorrido.","Aguanta un instante la contracción y permite que el rodillo suba despacio en 3 segundos sintiendo el estiramiento excéntrico."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Leg_Curl/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Leg_Curl/1.jpg"]', '[{"id":"romanian-deadlift","name":"Peso Muerto Rumano con Barra","nameEn":"Barbell Romanian Deadlift","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Hamstrings","primaryMuscleEs":"Isquiotibiales / Femoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Romanian_Deadlift/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Romanian_Deadlift/1.jpg"]},{"id":"dumbbell-rdl","name":"Peso Muerto Rumano con Mancuernas","nameEn":"Dumbbell Romanian Deadlift","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Hamstrings","primaryMuscleEs":"Isquiotibiales / Femoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff-Legged_Dumbbell_Deadlift/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff-Legged_Dumbbell_Deadlift/1.jpg"]},{"id":"trap-bar-deadlift-low-handles","name":"Peso Muerto en Barra Hexagonal (Asas Bajas)","nameEn":"Trap Bar Deadlift Low Handles","equipment":"Trap Bar","equipmentEs":"Barra Hexagonal","primaryMuscle":"Hamstrings","primaryMuscleEs":"Isquiotibiales / Femoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Trap_Bar_Deadlift/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Trap_Bar_Deadlift/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('lying-leg-curl-machine', 'Curl Femoral Tumbado en Máquina', 'Lying Leg Curl Machine', 'Hipertrofia', 'Hamstrings', 'Isquiotibiales / Femoral', '["Calves"]', 'Machine', 'Máquina de Palanca', 'Principiante', 'Aislamiento', 'Bisagra de Cadera', 'Flexión/Extensión', '', '["Acuéstate boca abajo en el banco de la máquina encajando los tobillos bajo el rodillo acolchado.","Sujeta firmemente las asas laterales y mantén la pelvis pegada al tapizado.","Flexiona las rodillas llevando los talones hacia los glúteos de forma decidida.","Desciende despacio resistiendo la carga hasta estirar casi por completo las piernas."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Leg_Curls/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Leg_Curls/1.jpg"]', '[{"id":"romanian-deadlift","name":"Peso Muerto Rumano con Barra","nameEn":"Barbell Romanian Deadlift","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Hamstrings","primaryMuscleEs":"Isquiotibiales / Femoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Romanian_Deadlift/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Romanian_Deadlift/1.jpg"]},{"id":"dumbbell-rdl","name":"Peso Muerto Rumano con Mancuernas","nameEn":"Dumbbell Romanian Deadlift","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Hamstrings","primaryMuscleEs":"Isquiotibiales / Femoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff-Legged_Dumbbell_Deadlift/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff-Legged_Dumbbell_Deadlift/1.jpg"]},{"id":"trap-bar-deadlift-low-handles","name":"Peso Muerto en Barra Hexagonal (Asas Bajas)","nameEn":"Trap Bar Deadlift Low Handles","equipment":"Trap Bar","equipmentEs":"Barra Hexagonal","primaryMuscle":"Hamstrings","primaryMuscleEs":"Isquiotibiales / Femoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Trap_Bar_Deadlift/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Trap_Bar_Deadlift/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('leg-extension-machine', 'Extensión de Cuádriceps en Máquina', 'Leg Extension Machine', 'Hipertrofia', 'Quads', 'Cuádriceps', '[]', 'Machine', 'Máquina de Palanca', 'Principiante', 'Aislamiento', 'Sentadilla', 'Flexión/Extensión', '', '["Siéntate con la espalda apoyada y los tobillos colocados detrás del rodillo inferior acolchado.","Agarra las asas laterales para fijar el torso en el asiento.","Extiende las piernas hacia arriba contrayendo los cuádriceps hasta quedar paralelas al suelo.","Mantén la contracción durante un segundo en la posición más alta y baja con control en 3 segundos."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Extensions/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Extensions/1.jpg"]', '[{"id":"barbell-squat","name":"Sentadilla de Espalda con Barra","nameEn":"Barbell Back Squat","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/1.jpg"]},{"id":"zercher-squat-barbell","name":"Sentadilla Zercher con Barra en el Pliegue de los Codos","nameEn":"Zercher Squat with Barbell in Elbow Crook","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Zercher_Squats/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Zercher_Squats/1.jpg"]},{"id":"safety-bar-squat","name":"Sentadilla con Barra de Seguridad (SSB Squat)","nameEn":"Safety Squat Bar (SSB) Squat","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('seated-calf-raise-machine', 'Elevación de Talones Sentado en Máquina (Sóleo)', 'Seated Calf Raise Machine', 'Hipertrofia', 'Calves', 'Gemelos / Pantorrillas', '[]', 'Machine', 'Máquina de Palanca', 'Principiante', 'Aislamiento', 'Sentadilla', 'Flexión/Extensión', '', '["Siéntate en la máquina de gemelos apoyando la parte delantera de los pies en la plataforma y los muslos bajo el acolchado.","Quita la palanca de seguridad y desciende los talones todo lo posible sintiendo el estiramiento profundo del sóleo.","Empuja sobre las puntas de los pies elevando los talones a la máxima altura.","Pausa un segundo arriba y baja despacio manteniendo una cadencia estricta."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Calf_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Calf_Raise/1.jpg"]', '[{"id":"standing-calf-raise","name":"Elevación de Gemelos de Pie con Barra","nameEn":"Standing Barbell Calf Raise","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Calves","primaryMuscleEs":"Gemelos / Pantorrillas","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Barbell_Calf_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Barbell_Calf_Raise/1.jpg"]},{"id":"smith-machine-standing-calf-raise","name":"Elevación de Talones de Pie en Máquina Smith","nameEn":"Smith Machine Standing Calf Raise on Block","equipment":"SmithMachine","equipmentEs":"Máquina Smith / Multipower","primaryMuscle":"Calves","primaryMuscleEs":"Gemelos / Pantorrillas","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Calf_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Calf_Raise/1.jpg"]},{"id":"single-leg-isometric-calf-raise","name":"Sostenimiento Isométrico de Gemelo en Punta de Pie","nameEn":"Single-Leg Isometric Calf Raise Hold","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Calves","primaryMuscleEs":"Gemelos / Pantorrillas","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Donkey_Calf_Raises/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Donkey_Calf_Raises/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('tibialis-raise-bodyweight', 'Elevación de Tibial Anterior contra la Pared', 'Wall Tibialis Raise', 'Rehabilitación', 'Calves', 'Gemelos / Pantorrillas', '[]', 'Bodyweight', 'Peso Corporal', 'Principiante', 'Aislamiento', 'Movilidad', 'Flexión/Extensión', '', '["Apoya la espalda contra una pared lisa y adelanta los pies a una distancia de uno o dos pasos con piernas rectas.","Manteniendo los talones pegados al suelo, eleva las puntas de los pies hacia las espinillas lo más alto posible.","Aprieta la musculatura anterior de la espinilla en la cima durante un segundo.","Baja las puntas de los pies rozando suavemente el suelo y repite de forma continua."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Calf_Raises/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Calf_Raises/1.jpg"]', '[{"id":"tibialis-raise-weighted-bar","name":"Elevación de Tibial con Barra de Tobillo (Tib Bar)","nameEn":"Weighted Tib Bar Tibialis Raise","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Calves","primaryMuscleEs":"Gemelos / Pantorrillas","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Dumbbell_Calf_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Dumbbell_Calf_Raise/1.jpg"]},{"id":"foam-roll-calves-gastrocnemius","name":"Autoliberación de Gemelos y Tendón de Aquiles","nameEn":"Foam Rolling Calves and Gastrocnemius","equipment":"FoamRoller","equipmentEs":"Rodillo de Espuma","primaryMuscle":"Calves","primaryMuscleEs":"Gemelos / Pantorrillas","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calves-SMR/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calves-SMR/1.jpg"]},{"id":"foam-roll-shins-tibialis","name":"Liberación Miofascial de Tibial Anterior","nameEn":"Foam Rolling Anterior Tibialis","equipment":"FoamRoller","equipmentEs":"Rodillo de Espuma","primaryMuscle":"Calves","primaryMuscleEs":"Gemelos / Pantorrillas","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Anterior_Tibialis-SMR/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Anterior_Tibialis-SMR/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('adductor-machine', 'Aductores en Máquina Sentado', 'Seated Hip Adductor Machine', 'Hipertrofia', 'Adductors', 'Aductores (Cara Interna)', '[]', 'Machine', 'Máquina de Palanca', 'Principiante', 'Aislamiento', 'Movilidad', 'Empuje', '', '["Siéntate en la máquina de aducción ajustando las almohadillas por la parte interna de las rodillas.","Abre las piernas a un rango cómodo donde sientas un estiramiento suave en la cara interna de los muslos.","Junta las rodillas empujando hacia el centro contrayendo los aductores de forma controlada.","Pausa un segundo en el cierre y abre las piernas despacio resistiendo el peso."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Thigh_Adductor/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Thigh_Adductor/1.jpg"]', '[{"id":"foam-roll-adductors","name":"Liberación de Aductores en Posición de Rana","nameEn":"Foam Rolling Adductor Complex","equipment":"FoamRoller","equipmentEs":"Rodillo de Espuma","primaryMuscle":"Adductors","primaryMuscleEs":"Aductores (Cara Interna)","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Adductor/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Adductor/1.jpg"]},{"id":"standing-hip-adduction-cable","name":"Aducción de Cadera de Pie en Polea","nameEn":"Standing Cable Hip Adduction","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Adductors","primaryMuscleEs":"Aductores (Cara Interna)","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Hip_Adduction/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Hip_Adduction/1.jpg"]},{"id":"frog-stretch-mobility","name":"Postura de la Rana (Frog Stretch)","nameEn":"Frog Mobility Stretch","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Adductors","primaryMuscleEs":"Aductores (Cara Interna)","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Groiners/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Groiners/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('abductor-machine', 'Abductores en Máquina Sentado (Glúteo Medio)', 'Seated Hip Abductor Machine', 'Hipertrofia', 'Abductors', 'Abductores (Glúteo Medio)', '["Glutes"]', 'Machine', 'Máquina de Palanca', 'Principiante', 'Aislamiento', 'Movilidad', 'Empuje', '', '["Siéntate apoyando la espalda contra el respaldo y coloca la parte externa de las rodillas contra los rodillos.","Empuja hacia afuera separando las piernas con fuerza del glúteo medio y abductores.","Mantén la apertura máxima un segundo y regresa despacio hasta la posición inicial sin dejar caer las placas."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Thigh_Abductor/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Thigh_Abductor/1.jpg"]', '[{"id":"foam-roll-it-band-tfl","name":"Liberación del Tensor de la Fascia Lata y Banda Iliotibial","nameEn":"Foam Rolling IT Band and Tensor Fasciae Latae","equipment":"FoamRoller","equipmentEs":"Rodillo de Espuma","primaryMuscle":"Abductors","primaryMuscleEs":"Abductores (Glúteo Medio)","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Iliotibial_Tract-SMR/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Iliotibial_Tract-SMR/1.jpg"]},{"id":"standing-hip-abduction-cable","name":"Abducción de Cadera de Pie en Polea","nameEn":"Standing Cable Hip Abduction","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Abductors","primaryMuscleEs":"Abductores (Glúteo Medio)","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Hip_Adduction/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Hip_Adduction/1.jpg"]},{"id":"side-lying-hip-abduction-straight-leg","name":"Elevación Lateral de Pierna Recta Tumbado","nameEn":"Side-Lying Straight Leg Hip Abduction","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Abductors","primaryMuscleEs":"Abductores (Glúteo Medio)","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Leg_Raises/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Leg_Raises/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('diamond-pushup', 'Flexiones Diamante', 'Diamond Push-Up', 'Calistenia', 'Triceps', 'Tríceps', '["Chest","Shoulders"]', 'Bodyweight', 'Peso Corporal', 'Intermedio', 'Compuesto', 'Empuje Horizontal', 'Empuje', '', '["Adopta la postura inicial de flexiones diamante asegurando alineación pélvica y core tenso.","Desciende el torso de forma controlada hasta el rango óptimo de estiramiento articular.","Empuja con potencia contra el punto de apoyo extendiendo los brazos a la posición inicial."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Push-Up_off_of_a_Dumbbell/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Push-Up_off_of_a_Dumbbell/1.jpg"]', '[{"id":"tate-press-dumbbells","name":"Press Tate con Mancuernas en Banco Plano","nameEn":"Flat Bench Dumbbell Tate Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tate_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tate_Press/1.jpg"]},{"id":"california-press-barbell","name":"Press California (Híbrido Cerrado + Press Francés)","nameEn":"Barbell California Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Barbell_Bench_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Barbell_Bench_Press/1.jpg"]},{"id":"cable-kickback-triceps","name":"Patada de Tríceps Unilateral en Polea Baja","nameEn":"Single-Arm Cable Triceps Kickback","equipment":"Cable","equipmentEs":"Polea con Cable","primaryMuscle":"Triceps","primaryMuscleEs":"Tríceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_One_Arm_Tricep_Extension/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_One_Arm_Tricep_Extension/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('wide-grip-pushup', 'Flexiones con Agarre Ancho', 'Wide Grip Push-Up', 'Calistenia', 'Chest', 'Pecho / Pectoral', '["Shoulders"]', 'Bodyweight', 'Peso Corporal', 'Principiante', 'Compuesto', 'Empuje Horizontal', 'Empuje', '', '["Adopta la postura inicial de flexiones con agarre ancho asegurando alineación pélvica y core tenso.","Desciende el torso de forma controlada hasta el rango óptimo de estiramiento articular.","Empuja con potencia contra el punto de apoyo extendiendo los brazos a la posición inicial."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push-Up_Wide/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push-Up_Wide/1.jpg"]', '[{"id":"ring-pushup","name":"Flexiones en Anillas de Gimnasia","nameEn":"Gymnastic Ring Push-Up","equipment":"Rings","equipmentEs":"Anillas de Gimnasia","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Push-Up/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Push-Up/1.jpg"]},{"id":"barbell-bench-press","name":"Press de Banca con Barra","nameEn":"Barbell Bench Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/1.jpg"]},{"id":"dumbbell-bench-press","name":"Press de Banca con Mancuernas","nameEn":"Dumbbell Bench Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('decline-pushup', 'Flexiones Declinadas con Pies Elevados', 'Decline Push-Up', 'Calistenia', 'Chest', 'Pecho / Pectoral', '["Shoulders","Triceps"]', 'Bodyweight', 'Peso Corporal', 'Intermedio', 'Compuesto', 'Empuje Horizontal', 'Empuje', '', '["Adopta la postura inicial de flexiones declinadas con pies elevados asegurando alineación pélvica y core tenso.","Desciende el torso de forma controlada hasta el rango óptimo de estiramiento articular.","Empuja con potencia contra el punto de apoyo extendiendo los brazos a la posición inicial."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Push-Up/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Push-Up/1.jpg"]', '[{"id":"ring-pushup","name":"Flexiones en Anillas de Gimnasia","nameEn":"Gymnastic Ring Push-Up","equipment":"Rings","equipmentEs":"Anillas de Gimnasia","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Push-Up/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Push-Up/1.jpg"]},{"id":"barbell-bench-press","name":"Press de Banca con Barra","nameEn":"Barbell Bench Press","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/1.jpg"]},{"id":"dumbbell-bench-press","name":"Press de Banca con Mancuernas","nameEn":"Dumbbell Bench Press","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Chest","primaryMuscleEs":"Pecho / Pectoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
