INSERT INTO exercises VALUES ('pistol-squat', 'Sentadilla Pistola a Una Pierna (Pistol Squat)', 'Pistol Squat', 'Calistenia', 'Quads', 'Cuádriceps', '["Glutes","Calves"]', 'Bodyweight', 'Peso Corporal', 'Avanzado', 'Compuesto', 'Sentadilla', 'Empuje', '', '["Sitúate en posición de partida para sentadilla pistola a una pierna (pistol squat) equilibrando el cuerpo.","Ejecuta el rango de recorrido completo manteniendo la tensión continua en quads.","Regresa a la postura inicial con control técnico riguroso."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Pistol_Squat/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Pistol_Squat/1.jpg"]', '[{"id":"barbell-squat","name":"Sentadilla de Espalda con Barra","nameEn":"Barbell Back Squat","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/1.jpg"]},{"id":"front-squat","name":"Sentadilla Frontal con Barra","nameEn":"Barbell Front Squat","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Barbell_Squat/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Barbell_Squat/1.jpg"]},{"id":"hack-squat","name":"Sentadilla Hack en Máquina","nameEn":"Hack Squat Machine","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hack_Squat/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hack_Squat/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name