INSERT INTO exercises VALUES ('nordic-hamstring-curl', 'Curl Nórdico de Isquiotibiales', 'Nordic Hamstring Curl', 'Calistenia', 'Hamstrings', 'Isquiotibiales / Femoral', '["Glutes","Calves"]', 'Bodyweight', 'Peso Corporal', 'Avanzado', 'Compuesto', 'Bisagra de Cadera', 'Empuje', '', '["Sitúate en posición de partida para curl nórdico de isquiotibiales equilibrando el cuerpo.","Ejecuta el rango de recorrido completo manteniendo la tensión continua en hamstrings.","Regresa a la postura inicial con control técnico riguroso."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Natural_Glute_Ham_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Natural_Glute_Ham_Raise/1.jpg"]', '[{"id":"romanian-deadlift","name":"Peso Muerto Rumano con Barra","nameEn":"Barbell Romanian Deadlift","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Hamstrings","primaryMuscleEs":"Isquiotibiales / Femoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Romanian_Deadlift/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Romanian_Deadlift/1.jpg"]},{"id":"dumbbell-rdl","name":"Peso Muerto Rumano con Mancuernas","nameEn":"Dumbbell Romanian Deadlift","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Hamstrings","primaryMuscleEs":"Isquiotibiales / Femoral","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff-Legged_Dumbbell_Deadlift/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff-Legged_Dumbbell_Deadlift/1.jpg"]},{"id":"single-leg-kettlebell-rdl","name":"Peso Muerto Rumano Unilateral con Pesa Rusa","nameEn":"Single-Leg Kettlebell Romanian Deadlift","equipment":"Kettlebell","equipmentEs":"Pesa Rusa (Kettlebell)","primaryMuscle":"Hamstrings","primaryMuscleEs":"Isquiotibiales / Femoral","images":["https://raw.githubusercontent.com/yuhonas/free-exerci