INSERT INTO exercises VALUES ('single-leg-glute-bridge', 'Puente de Glúteos a Una Pierna', 'Single-Leg Glute Bridge', 'Calistenia', 'Glutes', 'Glúteos', '["Hamstrings"]', 'Bodyweight', 'Peso Corporal', 'Principiante', 'Compuesto', 'Bisagra de Cadera', 'Empuje', '', '["Sitúate en posición de partida para puente de glúteos a una pierna equilibrando el cuerpo.","Ejecuta el rango de recorrido completo manteniendo la tensión continua en glutes.","Regresa a la postura inicial con control técnico riguroso."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single_Leg_Glute_Bridge/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single_Leg_Glute_Bridge/1.jpg"]', '[{"id":"barbell-hip-thrust","name":"Hip Thrust con Barra","nameEn":"Barbell Hip Thrust","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Glutes","primaryMuscleEs":"Glúteos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hip_Thrust/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hip_Thrust/1.jpg"]},{"id":"dumbbell-glute-bridge","name":"Puente de Glúteos con Mancuerna","nameEn":"Dumbbell Glute Bridge","equipment":"Dumbbell","equipmentEs":"Mancuernas","primaryMuscle":"Glutes","primaryMuscleEs":"Glúteos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Glute_Bridge/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Glute_Bridge/1.jpg"]},{"id":"hip-thrust-barbell","name":"Hip Thrust con Barra (Empuje de Cadera)","nameEn":"Barbell Hip Thrust","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Glutes","primaryMuscleEs":"Glúteos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hip_Thrust/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hip_Thrust/1.jpg"]}]') ON CO