INSERT INTO exercises VALUES ('calf-raise-single-leg-bodyweight', 'Elevación de Talón Unilateral en Escalón', 'Single-Leg Calf Raise on Step', 'Calistenia', 'Calves', 'Gemelos / Pantorrillas', '[]', 'Bodyweight', 'Peso Corporal', 'Principiante', 'Compuesto', 'Sentadilla', 'Empuje', '', '["Sitúate en posición de partida para elevación de talón unilateral en escalón equilibrando el cuerpo.","Ejecuta el rango de recorrido completo manteniendo la tensión continua en calves.","Regresa a la postura inicial con control técnico riguroso."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Seated_One-Leg_Calf_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Seated_One-Leg_Calf_Raise/1.jpg"]', '[{"id":"donkey-calf-raise-machine","name":"Elevación de Gemelos Estilo Burro (Donkey Calf)","nameEn":"Donkey Calf Raise Machine","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Calves","primaryMuscleEs":"Gemelos / Pantorrillas","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Donkey_Calf_Raises/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Donkey_Calf_Raises/1.jpg"]},{"id":"leg-press-calf-raise","name":"Elevación de Talones en Prensa de Piernas","nameEn":"Leg Press Toe Press / Calf Raise","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Calves","primaryMuscleEs":"Gemelos / Pantorrillas","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Press_On_The_Leg_Press_Machine/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Press_On_The_Leg_Press_Machine/1.jpg"]},{"id":"smith-machine-standing-calf-raise","name":"Elevación de Talones de Pie en Máquina Smith","nameEn":"Smith Machine Standing Calf Raise on Block","equipment":"SmithMachine","equipmentEs":"Máquina Smith / Multipower","primaryMuscle":"Calves","primaryMuscleEs":"Gemelos / Pantorrillas","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Calf_Raise/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Calf_Raise/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
