INSERT INTO exercises VALUES ('jumping-jacks-cardio', 'Saltos de Tijera (Jumping Jacks)', 'Jumping Jacks', 'Calentamiento', 'Cardio', 'Sistema Cardiovascular', '["Calves","Shoulders"]', 'Bodyweight', 'Peso Corporal', 'Principiante', 'Compuesto', 'Cardiovascular', 'Cardio', '', '["Inicia el movimiento dinámico de saltos de tijera (jumping jacks) a ritmo moderado y progresivo.","Aumenta la amplitud y fluidez a medida que la temperatura corporal y lubricación sinovial se incrementan.","Finaliza manteniendo la respiración rítmica y el control postural."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Star_Jump/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Star_Jump/1.jpg"]', '[{"id":"jump-rope-basic-bounce","name":"Salto con Cuerda / Comba Rítmica Básica","nameEn":"Basic Jump Rope Bounce","equipment":"Rope","equipmentEs":"Cuerda de Batalla","primaryMuscle":"Cardio","primaryMuscleEs":"Sistema Cardiovascular","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rope_Jumping/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rope_Jumping/1.jpg"]},{"id":"treadmill-run","name":"Carrera en Cinta","nameEn":"Treadmill Run","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Cardio","primaryMuscleEs":"Sistema Cardiovascular","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jogging_Treadmill/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jogging_Treadmill/1.jpg"]},{"id":"stationary-bike","name":"Bicicleta Estática","nameEn":"Stationary Bike","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Cardio","primaryMuscleEs":"Sistema Cardiovascular","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bicycling_Stationary/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bicyc