INSERT INTO exercises VALUES ('box-jump-standard', 'Salto al Cajón Pliométrico', 'Standard Plyometric Box Jump', 'Pliométrico', 'Quads', 'Cuádriceps', '["Glutes","Calves"]', 'Box', 'Cajón Pliométrico', 'Intermedio', 'Compuesto', 'Explosivo', 'Empuje', '', '["Carga elástica rápida mediante flexión explosiva de tobillos, rodillas y caderas para salto al cajón pliométrico.","Extiende con potencia triple (tobillos, rodillas y caderas) propulsando el cuerpo en el aire.","Aterriza de puntillas flexionando articulaciones para amortiguar el impacto de forma silenciosa."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Box_Jump/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Box_Jump/1.jpg"]', '[{"id":"vertical-jump-countermovement","name":"Salto Vertical con Contramovimiento (CMJ)","nameEn":"Countermovement Vertical Jump (CMJ)","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rocket_Jump/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rocket_Jump/1.jpg"]},{"id":"split-squat-jump","name":"Salto en Tijera Alternando Piernas en el Aire","nameEn":"Jumping Split Squat Lunges","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Jump/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Jump/1.jpg"]},{"id":"jump-squat-plyometric","name":"Sentadilla con Salto Vertical Continuo","nameEn":"Continuous Plyometric Jump Squat","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Freehand_Jump_Squat/0.jpg","http