INSERT INTO exercises VALUES ('power-clean-barbell', 'Power Clean con Barra desde el Suelo', 'Barbell Power Clean from Floor', 'Olímpico', 'Glutes', 'Glúteos', '["Hamstrings","Traps","Back","Quads"]', 'Barbell', 'Barra Olímpica', 'Intermedio', 'Compuesto', 'Explosivo', 'Tirón', '', '["Ajusta el agarre reglamentario con gancho (hook grip) y la postura de salida para power clean con barra desde el suelo.","Ejecuta el primer tirón controlado manteniendo el ángulo de espalda neutro constante.","Detona la extensión triple explosiva al pasar las rodillas e ingresa con rapidez bajo la barra.","Recupera la vertical erguida asegurando el control total del peso sobre la cabeza o sobre los hombros."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean/1.jpg"]', '[{"id":"skater-jumps-warmup","name":"Saltos de Patinador Laterales (Skater Hops)","nameEn":"Lateral Skater Hops","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Glutes","primaryMuscleEs":"Glúteos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lateral_Bound/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lateral_Bound/1.jpg"]},{"id":"double-kettlebell-snatch","name":"Snatch Simultáneo con Dos Pesas Rusas","nameEn":"Double Kettlebell Snatch","equipment":"Kettlebell","equipmentEs":"Pesa Rusa (Kettlebell)","primaryMuscle":"Glutes","primaryMuscleEs":"Glúteos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Double_Kettlebell_Snatch/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Double_Kettlebell_Snatch/1.jpg"]},{"id":"broad-jump-standing","name":"Salto Horizontal de Longitud a Dos Pies","nameEn":"Standing Long Jump (Broad Jump)","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Glutes","primaryMuscleEs":"Glúteos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Long_Jump/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Long_Jump/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('hang-clean-barbell', 'Hang Clean con Barra desde Rodillas', 'Barbell Hang Clean (Hang Power Clean)', 'Olímpico', 'Glutes', 'Glúteos', '["Hamstrings","Traps"]', 'Barbell', 'Barra Olímpica', 'Intermedio', 'Compuesto', 'Explosivo', 'Tirón', '', '["Ajusta el agarre reglamentario con gancho (hook grip) y la postura de salida para hang clean con barra desde rodillas.","Ejecuta el primer tirón controlado manteniendo el ángulo de espalda neutro constante.","Detona la extensión triple explosiva al pasar las rodillas e ingresa con rapidez bajo la barra.","Recupera la vertical erguida asegurando el control total del peso sobre la cabeza o sobre los hombros."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hang_Clean/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hang_Clean/1.jpg"]', '[{"id":"skater-jumps-warmup","name":"Saltos de Patinador Laterales (Skater Hops)","nameEn":"Lateral Skater Hops","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Glutes","primaryMuscleEs":"Glúteos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lateral_Bound/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lateral_Bound/1.jpg"]},{"id":"double-kettlebell-snatch","name":"Snatch Simultáneo con Dos Pesas Rusas","nameEn":"Double Kettlebell Snatch","equipment":"Kettlebell","equipmentEs":"Pesa Rusa (Kettlebell)","primaryMuscle":"Glutes","primaryMuscleEs":"Glúteos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Double_Kettlebell_Snatch/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Double_Kettlebell_Snatch/1.jpg"]},{"id":"broad-jump-standing","name":"Salto Horizontal de Longitud a Dos Pies","nameEn":"Standing Long Jump (Broad Jump)","equipment":"Bodyweight","equipmentEs":"Peso Corporal","primaryMuscle":"Glutes","primaryMuscleEs":"Glúteos","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Long_Jump/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Long_Jump/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
INSERT INTO exercises VALUES ('clean-and-jerk-olympic', 'Dos Tiempos Olímpico Completo (Clean & Jerk)', 'Olympic Clean and Jerk', 'Olímpico', 'Quads', 'Cuádriceps', '["Shoulders","Glutes","Traps","Triceps"]', 'Barbell', 'Barra Olímpica', 'Avanzado', 'Compuesto', 'Explosivo', 'Tirón', '', '["Ajusta el agarre reglamentario con gancho (hook grip) y la postura de salida para dos tiempos olímpico completo (clean & jerk).","Ejecuta el primer tirón controlado manteniendo el ángulo de espalda neutro constante.","Detona la extensión triple explosiva al pasar las rodillas e ingresa con rapidez bajo la barra.","Recupera la vertical erguida asegurando el control total del peso sobre la cabeza o sobre los hombros."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_and_Jerk/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_and_Jerk/1.jpg"]', '[{"id":"box-jump-standard","name":"Salto al Cajón Pliométrico","nameEn":"Standard Plyometric Box Jump","equipment":"Box","equipmentEs":"Cajón Pliométrico","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Box_Jump/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Box_Jump/1.jpg"]},{"id":"box-jump-step-down","name":"Salto al Cajón con Bajada Caminando","nameEn":"Box Jump with Step-Down","equipment":"Box","equipmentEs":"Cajón Pliométrico","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Box_Jump/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Box_Jump/1.jpg"]},{"id":"depth-jump-reactive","name":"Salto de Profundidad Reactivo (Depth Jump)","nameEn":"Depth Jump for Reactive Elastic Power","equipment":"Box","equipmentEs":"Cajón Pliométrico","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images