INSERT INTO exercises VALUES ('scapular-push-up-plus', 'Flexiones Escapulares (Push-Up Plus para Serrato)', 'Scapular Push-Up Plus for Serratus Anterior', 'Rehabilitación', 'Serratus', 'Serrato Anterior', '["Chest","Triceps"]', 'Bodyweight', 'Peso Corporal', 'Principiante', 'Aislamiento', 'Empuje Horizontal', 'Estático', '', '["Colócate en la posición indicada para flexiones escapulares (push-up plus para serrato) con atención rigurosa a la postura anatómica neutra.","Realiza la contracción o mantenimiento isométrico suave focalizando la conexión neuromuscular en serratus.","Regresa despacio evitando compensaciones o movimientos de torsión en articulaciones adyacentes."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pushups/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pushups/1.jpg"]', '[{"id":"serratus-wall-slide-foam-roller","name":"Deslizamiento en Pared con Rodillo para Serrato","nameEn":"Foam Roller Serratus Wall Slide","equipment":"FoamRoller","equipmentEs":"Rodillo de Espuma","primaryMuscle":"Serratus","primaryMuscleEs":"Serrato Anterior","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rhomboids-SMR/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rhomboids-SMR/1.jpg"]}]') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, images = EXCLUDED.images, substitutes = EXCLUDED.substitutes;
