INSERT INTO exercises VALUES ('trx-overhead-squat', 'Sentadilla Profunda con Brazos en Y en TRX', 'TRX Overhead Deep Squat Mobility', 'Funcional', 'Quads', 'Cuádriceps', '["Shoulders","Back"]', 'TRX', 'TRX / Suspensión', 'Principiante', 'Compuesto', 'Sentadilla', 'Empuje', '', '["Ajusta la longitud de las correas y fija los anclajes con tensión constante para sentadilla profunda con brazos en y en trx.","Mantén la alineación axial de la columna vertebral y activa los estabilizadores del core.","Ejecuta el rango de movimiento suavemente aprovechando la inestabilidad de las correas."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Split_Squat/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Split_Squat/1.jpg"]', '[{"id":"sled-push-prowler","name":"Empuje de Trineo Pesado (Prowler Sled Push)","nameEn":"Heavy Prowler Sled Push","equipment":"Sled","equipmentEs":"Trineo de Empuje (Prowler)","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sled_Push/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sled_Push/1.jpg"]},{"id":"sled-drag-backward","name":"Arrastre de Trineo Marchando hacia Atrás","nameEn":"Backward Sled Drag for Knee Resilience","equipment":"Sled","equipmentEs":"Trineo de Empuje (Prowler)","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Backward_Drag/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Backward_Drag/1.jpg"]},{"id":"barbell-squat","name":"Sentadilla de Espalda con Barra","nameEn":"Barbell Back Squat","equipment":"Barbell","equipmentEs":"Barra Olímpica","primaryMuscle":"Quads","primaryMuscleEs":"Cuádriceps","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/0.jpg",