INSERT INTO exercises VALUES ('assault-bike-sprint', 'Sprint Máximo en Bicicleta de Aire (Air Bike)', 'Air Bike All-Out Sprint', 'Cardio', 'Cardio', 'Sistema Cardiovascular', '["Quads","Shoulders","Lats"]', 'Bodyweight', 'Peso Corporal', 'Principiante', 'Compuesto', 'Cardiovascular', 'Cardio', '', '["Mantén la postura erguida y comienza el ritmo de sprint máximo en bicicleta de aire (air bike) a una cadencia sostenida.","Enfoca el esfuerzo en la respiración diafragmática continua sin apneas prolongadas.","Finaliza manteniendo la desaceleración gradual para permitir la recuperación cardíaca."]', '[]', '["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bicycling_Stationary/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bicycling_Stationary/1.jpg"]', '[{"id":"treadmill-run","name":"Carrera en Cinta","nameEn":"Treadmill Run","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Cardio","primaryMuscleEs":"Sistema Cardiovascular","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jogging_Treadmill/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jogging_Treadmill/1.jpg"]},{"id":"stationary-bike","name":"Bicicleta Estática","nameEn":"Stationary Bike","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Cardio","primaryMuscleEs":"Sistema Cardiovascular","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bicycling_Stationary/0.jpg","https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bicycling_Stationary/1.jpg"]},{"id":"rowing-machine","name":"Máquina de Remo (Ergómetro)","nameEn":"Rowing Machine","equipment":"Machine","equipmentEs":"Máquina de Palanca","primaryMuscle":"Cardio","primaryMuscleEs":"Sistema Cardiovascular","images":["https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rowing_Stationary/0.jpg","https://raw.githubusercon